        // it has none.
        const sexSamples = () => {
            const withCalls = SAMPLES.map((nm, si) => ({ nm: nm, si: si })).filter((x) => { const c3 = phaseCounts(x.si); return c3 && c3.all > 0; });
            return withCalls.length ? withCalls.slice(0, GT_MAX) : (vtotal ? [{ nm: '', si: -1 }] : []);
        };
