        // Which column is the tumour and which the normal, inside ONE file. Named columns
        // decide it outright; otherwise every ordered pair is offered, because guessing
        // which of two unnamed samples is the normal is the kind of guess that inverts a
        // whole result.
        const qcPairSpecs = () => {
            const out = [];
            const t = SAMPLES.findIndex((x) => /tumou?r/i.test(x));
            const n = SAMPLES.findIndex((x) => /normal|germline|blood/i.test(x));
            if (t >= 0 && n >= 0 && t !== n) out.push({ tumor: t, normal: n, named: true });
            else for (let a = 0; a < SAMPLES.length; a++) for (let b = 0; b < SAMPLES.length; b++) {
                if (a !== b) out.push({ tumor: a, normal: b, named: false });
            }
            return out;
        };

        // ---- 1. SOMATIC CALLS THE NORMAL ALSO CARRIES ---------------------------------
        const nsupRun = async (spec) => {
            clearWorking();
            qcClearHl();
            const perChrom = [];
            let calls = 0, carried = 0, carriedPass = 0, clean = 0, unread = 0, marked = 0;
            const rows = [];
            for (let ci = 0; ci < drawn.length; ci++) {
                const d = vdata[ci];
                if (!d || !d.n || d.gtw <= Math.max(spec.tumor, spec.normal)) continue;
                graph.setMessage(' Reading ' + drawn[ci].name + ' for somatic calls the normal carries… ');
                let c = 0, k2 = 0;
                for (let k = 0; k < d.n; k++) {
                    if (gtOf(d, k, spec.tumor) < GT_HET) continue;
                    if (gtOf(d, k, spec.normal) >= GT_HET) continue;      // the file already says the normal has it
                    calls++;
                    const b = bafOf(d, k, spec.normal);
                    if (b < 0) { unread++; continue; }
                    // No confidence gate here. MuTect2 fails exactly these calls with
                    // alt_allele_in_normal, which grades them low -- gating on that would hide
                    // the calls this is looking for. Whether the caller already caught one is
                    // reported beside it instead.
                    if (b >= NSUP_BAF) {
                        carried++; c++;
                        const passed = !(d.rconf && d.rconf[k] === CONF_LOW);
                        if (passed) carriedPass++;
                        d.hl[k] = HL_NSUP; marked++;
                        if (rows.length < 50000) {
                            const ab = allelesAt(ci, k);
                            rows.push({ chrom: drawn[ci].name, pos: d.pos[k], ref: ab[0], alt: ab[1],
                                tumor_gt: GT_TEXT[gtOf(d, k, spec.tumor)] || '', normal_gt: GT_TEXT[gtOf(d, k, spec.normal)] || '',
                                caller_filter: passed ? 'passed' : 'failed', normal_allele_fraction: b.toFixed(3), tumor_allele_fraction: (bafOf(d, k, spec.tumor) >= 0 ? bafOf(d, k, spec.tumor).toFixed(3) : '') });
                        }
                    } else clean++;
                    if (++k2 % 50000 === 0) await new Promise((r2) => setTimeout(r2, 0));
                }
                if (c) perChrom.push({ name: drawn[ci].name, n: c });
            }
            nsupResult = { spec: spec, calls: calls, carried: carried, carriedPass: carriedPass, clean: clean, unread: unread, perChrom: perChrom, rows: rows, marked: marked };
            graph.setMessage(' ' + carried.toLocaleString() + ' somatic call' + (carried === 1 ? '' : 's') + ' the normal carries. ');
            if (marked) qcMarkAndShow(HL_NSUP); else legendRefresh();
            nsupMenu();
        };
        const nsupMenu = () => {
            try { if (typeof hideAllModal === 'function') hideAllModal(); } catch (e) { }
            const R = nsupResult;
            const books = [];
            if (!R) {
                const specs = qcPairSpecs();
                books.push({ section: 'Somatic calls the normal carries', note: true,
                    title: 'A call the tumour carries and the normal is written as not carrying is a somatic call. When the normal’s '
                        + 'OWN READS show the allele anyway, it is a germline variant, contamination, or an artefact both samples '
                        + 'share — whatever the genotype column says. This reads the normal’s reads at every such call.' });
                if (SAMPLES.length < 2) {
                    books.push({ section: 'Somatic calls the normal carries', accent: 'choose', title: 'Load a tumour/normal callset',
                        badge: 'needs two samples', icon: 'upload_file', ready: true,
                        blurb: 'One file holding a TUMOR and a NORMAL column — MuTect2, Strelka and SomaticSniper all write that.',
                        open: () => uploadMenu() });
                } else {
                    specs.forEach((sp) => books.push({ section: 'Somatic calls the normal carries', accent: 'run',
                        title: SAMPLES[sp.tumor] + ' as the tumour, ' + SAMPLES[sp.normal] + ' as the normal',
                        badge: sp.named ? 'named in the file' : 'your choice', icon: 'fact_check', ready: true,
                        blurb: 'Every call in ' + SAMPLES[sp.tumor] + ' that ' + SAMPLES[sp.normal] + ' is not genotyped as carrying, checked '
                            + 'against ' + SAMPLES[sp.normal] + '’s reads: at least a tenth of them carrying the allele, on a call not graded low.',
                        open: () => nsupRun(sp) }));
                }
            } else {
                const pc = (a, b) => (b ? (100 * a / b).toFixed(1) + '%' : '—');
                books.push({ section: 'Somatic calls the normal carries', note: true, mono: true, title:
                      'somatic calls read       ' + R.calls.toLocaleString() + '\n'
                    + 'normal carries the allele ' + R.carried.toLocaleString() + '   (' + pc(R.carried, R.calls) + ')\n'
                    + '  the caller flagged it    ' + (R.carried - R.carriedPass).toLocaleString() + '\n'
                    + '  no flag from the caller  ' + R.carriedPass.toLocaleString() + '\n'
                    + 'normal reads are clean    ' + R.clean.toLocaleString() + '   (' + pc(R.clean, R.calls) + ')\n'
                    + 'normal has no read count  ' + R.unread.toLocaleString() + '   (' + pc(R.unread, R.calls) + ')' });
                books.push({ section: 'Somatic calls the normal carries', note: true,
                    title: (R.carried
                        ? R.carried.toLocaleString() + ' call' + (R.carried === 1 ? '' : 's') + ' in ' + SAMPLES[R.spec.tumor] + ' are supported by '
                          + SAMPLES[R.spec.normal] + '’s own reads, and are marked on the genome. '
                          + (R.carriedPass
                              ? R.carriedPass.toLocaleString() + ' of them carry no FILTER flag or low QUAL from the caller \u2014 those are the ones to treat as germline or '
                                + 'contaminated before any is reasoned from as somatic.'
                              : 'The caller had already flagged every one of them, so its unflagged calls are clean on this count.')
                        : 'No somatic call is supported by the normal’s reads.')
                        + (R.unread ? ' ' + R.unread.toLocaleString() + ' could not be judged: the normal had fewer than eight reads there, or the file '
                            + 'carries no read counts for it.' : '') });
                R.perChrom.sort((a, b) => b.n - a.n).slice(0, 24).forEach((c) => books.push({ section: 'By chromosome',
                    title: c.name, badge: c.n.toLocaleString(), icon: 'zoom_in', ready: true,
                    blurb: c.n.toLocaleString() + ' call' + (c.n === 1 ? '' : 's') + ' the normal carries.',
                    open: () => { const ci = chromIndexOf(c.name); if (ci >= 0) goView({ x0: barLeft(ci) - 0.6 * SLOT, x1: barRight(ci) + 0.6 * SLOT, y0: wy(drawn[ci].length), y1: wy(0) }); } }));
                books.push({ section: 'Take it away', title: 'Download them as CSV', badge: R.rows.length.toLocaleString() + ' rows', icon: 'file_download',
                    ready: R.rows.length > 0, readyNote: 'nothing flagged',
                    blurb: 'Position, alleles, both genotypes and both allele fractions for every flagged call' + (R.carried > R.rows.length ? ' (the first 50,000)' : '') + '.',
                    open: () => { try { dlSaveText(dlToCSV(R.rows), dlSafe(dlSpecies() + '_somatic_calls_the_normal_carries') + '.csv', 'text/csv'); dlMsg('Downloaded.'); } catch (e) { dlErr('Could not build the CSV: ' + e); } } });
                books.push({ section: 'Take it away', title: 'Run it again', badge: 'again', icon: 'refresh', ready: true,
                    blurb: 'With a different tumour and normal, or after loading more.', open: () => { nsupResult = null; nsupMenu(); } });
            }
            books.push({ section: 'Back', title: 'Check the calls', badge: 'back', icon: 'arrow_back', back: true, ready: true,
                blurb: 'The other checks on what is loaded.', open: () => qcMenu() });
            exec('baja/lib/shelf.js', { id: 'baja-karyo-analysis', title: 'Somatic calls the normal carries',
                subtitle: R ? (R.carried.toLocaleString() + ' of ' + R.calls.toLocaleString() + ' flagged') : 'read the normal’s reads at every somatic call',
                graph: graph, books: books });
        };

        // ---- 2. GENOTYPES THE READS CONTRADICT ----------------------------------------
        const gtReadRun = async () => {
            clearWorking();
            qcClearHl();
            const W = Math.min(SAMPLES.length, GT_MAX);
            const per = [];
            for (let si = 0; si < W; si++) per.push({ si: si, read: 0, homLow: 0, hetHigh: 0, hetNone: 0 });
            const rows = [];
            let marked = 0;
            // A tumour's 0/1 at 2% is a subclone, not a mistake: a somatic caller writes 0/1
            // for any call it makes, whatever the fraction. Only a normal, or an unnamed
            // sample, is held to "a heterozygote shows its allele".
            const named = qcPairSpecs().find((x) => x.named);
            const tumourCol = named ? named.tumor : -1;
            for (let ci = 0; ci < drawn.length; ci++) {
                const d = vdata[ci];
                if (!d || !d.n || !d.gtw) continue;
                graph.setMessage(' Comparing genotypes with reads on ' + drawn[ci].name + '… ');
                for (let k = 0; k < d.n; k++) {
                    for (let si = 0; si < W && si < d.gtw; si++) {
                        const g = gtOf(d, k, si);
                        if (g < GT_HET || g === GT_OTHER) continue;
                        const b = bafOf(d, k, si);
                        if (b < 0 || confOf(d, k, si) === CONF_LOW) continue;
                        per[si].read++;
                        let why = '';
                        // The bands are wide on purpose: a tumour is impure and aneuploid, and an
                        // allele fraction of 0.62 on a 1/1 is ordinary. These are the calls the
                        // reads plainly disagree with, not the ones that are merely imperfect.
                        if ((g === GT_HOM || g === GT_HOMP) && b < 0.60) { why = 'called homozygous, reads say heterozygous'; per[si].homLow++; }
                        else if ((g === GT_HET || g === GT_HAP1 || g === GT_HAP2) && b >= 0.95) { why = 'called heterozygous, reads say homozygous'; per[si].hetHigh++; }
                        else if ((g === GT_HET || g === GT_HAP1 || g === GT_HAP2) && b < 0.03 && si !== tumourCol) { why = 'called heterozygous, reads barely show it'; per[si].hetNone++; }
                        if (!why) continue;
                        if (!d.hl[k]) { d.hl[k] = HL_GTREAD; marked++; }
                        if (rows.length < 50000) {
                            const ab = allelesAt(ci, k);
                            rows.push({ chrom: drawn[ci].name, pos: d.pos[k], ref: ab[0], alt: ab[1], sample: SAMPLES[si],
                                genotype: GT_TEXT[g], allele_fraction: b.toFixed(3), disagreement: why });
                        }
                    }
                    if (k % 50000 === 49999) await new Promise((r2) => setTimeout(r2, 0));
                }
            }
            gtReadResult = { per: per, rows: rows, marked: marked, tumourCol: tumourCol };
            graph.setMessage(' ' + marked.toLocaleString() + ' call' + (marked === 1 ? '' : 's') + ' whose genotype the reads contradict. ');
            if (marked) qcMarkAndShow(HL_GTREAD); else legendRefresh();
            gtReadMenu();
        };
        const gtReadMenu = () => {
            try { if (typeof hideAllModal === 'function') hideAllModal(); } catch (e) { }
            const R = gtReadResult;
            const books = [];
            books.push({ section: 'Genotypes the reads contradict', note: true,
                title: 'A caller’s genotype is a decision it made once; the allele depths are what it made it from. On calls that '
                    + 'passed their filters, where they plainly disagree — a homozygous call under 60% of the reads, a heterozygous one over 95% or under 3% — the reads are '
                    + 'the better witness, and every analysis here that reasons from genotypes inherits the caller’s mistake.' });
            if (!R) {
                const anyReads = vdata.some((d) => d && d.baf);
                books.push({ section: 'Genotypes the reads contradict', accent: anyReads ? 'run' : 'choose',
                    title: anyReads ? 'Compare every genotype with its reads' : 'Load a VCF with read counts',
                    badge: anyReads ? SAMPLES.length + ' sample' + (SAMPLES.length === 1 ? '' : 's') : 'needs AD or DP4', icon: 'rule', ready: true,
                    blurb: anyReads ? 'Every genotyped call, every sample, eight reads or more.'
                        : 'This needs allele depths — AD, or DP4 for SomaticSniper-style files. Nothing loaded carries them.',
                    open: () => { if (anyReads) gtReadRun(); else uploadMenu(); } });
            } else {
                const pc = (a, b) => (b ? (100 * a / b).toFixed(1) + '%' : '—');
                R.per.filter((x) => x.read).forEach((x) => books.push({ section: 'By sample', note: true, mono: true, title:
                      SAMPLES[x.si] + '   (' + x.read.toLocaleString() + ' genotyped calls with reads)\n'
                    + '  homozygous call, reads heterozygous   ' + x.homLow.toLocaleString() + '   ' + pc(x.homLow, x.read) + '\n'
                    + '  heterozygous call, reads homozygous   ' + x.hetHigh.toLocaleString() + '   ' + pc(x.hetHigh, x.read) + '\n'
                    + (x.si === R.tumourCol ? '  (a tumour\u2019s low fractions are subclones, not counted)'
                        : '  heterozygous call, reads barely show  ' + x.hetNone.toLocaleString() + '   ' + pc(x.hetNone, x.read)) }));
                books.push({ section: 'Take it away', title: 'Download them as CSV', badge: R.rows.length.toLocaleString() + ' rows', icon: 'file_download',
                    ready: R.rows.length > 0, readyNote: 'nothing flagged',
                    blurb: 'Position, alleles, sample, genotype, allele fraction and which way they disagree.',
                    open: () => { try { dlSaveText(dlToCSV(R.rows), dlSafe(dlSpecies() + '_genotypes_the_reads_contradict') + '.csv', 'text/csv'); dlMsg('Downloaded.'); } catch (e) { dlErr('Could not build the CSV: ' + e); } } });
                books.push({ section: 'Take it away', title: 'Run it again', badge: 'again', icon: 'refresh', ready: true,
                    blurb: 'After loading more.', open: () => { gtReadResult = null; gtReadMenu(); } });
            }
            books.push({ section: 'Back', title: 'Check the calls', badge: 'back', icon: 'arrow_back', back: true, ready: true,
                blurb: 'The other checks on what is loaded.', open: () => qcMenu() });
            exec('baja/lib/shelf.js', { id: 'baja-karyo-analysis', title: 'Genotypes the reads contradict',
                subtitle: R ? (R.marked.toLocaleString() + ' calls marked') : 'where a caller’s genotype and its own reads disagree',
                graph: graph, books: books });
        };

        // ---- 3. MUTATIONAL SPECTRUM ---------------------------------------------------
        //
        // The six classes, folded onto the pyrimidine of the pair so C>T and G>A are one
        // class, as every signature study writes them. Without the base either side this is
        // not a signature -- APOBEC and ageing both write C>T and only the context tells them
        // apart -- and the panel says so rather than naming a process it cannot see.
        const SBS6 = ['C>A', 'C>G', 'C>T', 'T>A', 'T>C', 'T>G'];
        const SBS_COMP = { A: 'T', C: 'G', G: 'C', T: 'A' };
        const spectrumOf = (filterFn) => {
            const cnt = { 'C>A': 0, 'C>G': 0, 'C>T': 0, 'T>A': 0, 'T>C': 0, 'T>G': 0 };
            let n = 0;
            for (let ci = 0; ci < drawn.length; ci++) {
                const d = vdata[ci];
                if (!d || !d.n) continue;
                for (let k = 0; k < d.n; k++) {
                    if (filterFn && !filterFn(d, k)) continue;
                    const ab = allelesAt(ci, k);
                    let r0 = ab[0], a0 = ab[1];
                    if (r0.length !== 1 || a0.length !== 1 || !SBS_COMP[r0] || !SBS_COMP[a0] || r0 === a0) continue;
                    if (r0 === 'G' || r0 === 'A') { r0 = SBS_COMP[r0]; a0 = SBS_COMP[a0]; }
                    cnt[r0 + '>' + a0]++; n++;
                }
            }
            const ti = cnt['C>T'] + cnt['T>C'];
            return { cnt: cnt, n: n, tiTv: (n - ti) ? ti / (n - ti) : 0 };
        };
        const spectrumBars = (S) => {
            const max = Math.max(1, ...SBS6.map((k) => S.cnt[k]));
            return SBS6.map((k) => {
                const v = S.cnt[k], w = Math.round(28 * v / max);
                return k + '  ' + '█'.repeat(w) + ' '.repeat(28 - w) + '  ' + v.toLocaleString().padStart(9)
                    + '  ' + (S.n ? (100 * v / S.n).toFixed(1) : '0.0').padStart(5) + '%';
            }).join('\n') + '\n\n' + S.n.toLocaleString() + ' single-base substitutions   Ti/Tv ' + S.tiTv.toFixed(2);
        };
        const spectrumMenu = () => {
            try { if (typeof hideAllModal === 'function') hideAllModal(); } catch (e) { }
            const books = [];
            const sc = sideCounts();
            books.push({ section: 'Mutational spectrum', note: true,
                title: 'The six substitution classes, each folded onto its pyrimidine (C>T and G>A are one class). A tumour’s own '
                    + 'processes write this profile — C>T most often from deamination with age, C>A from oxidative damage and tobacco, '
                    + 'T>A and T>C from others — which is why a germline Ti/Tv cannot judge a somatic callset. It is not a signature: '
                    + 'the bases either side are what separate APOBEC from ageing, and they are not read here.' });
            const groups = [];
            if (sc.left && sc.right) {
                groups.push({ name: sideName(0), fn: (d, k) => !(d.side && d.side[k]) });
                groups.push({ name: sideName(1), fn: (d, k) => !!(d.side && d.side[k]) });
            } else groups.push({ name: 'everything loaded', fn: null });
            // In a tumour/normal file, the calls the tumour carries and the normal does not
            // are the somatic ones -- the spectrum worth reading.
            // One file only: with two, a sample column means a different thing on each side.
            const pair = (sc.left && sc.right) ? null : qcPairSpecs().find((x) => x.named);
            if (pair) groups.push({ name: SAMPLES[pair.tumor] + ' only (somatic)',
                fn: (d, k) => d.gtw > Math.max(pair.tumor, pair.normal) && gtOf(d, k, pair.tumor) >= GT_HET && gtOf(d, k, pair.normal) < GT_HET });
            let any = false;
            groups.forEach((g) => {
                const S = spectrumOf(g.fn);
                if (!S.n) return;
                any = true;
                books.push({ section: g.name, note: true, mono: true, title: spectrumBars(S) });
            });
            if (!any) books.push({ section: 'Mutational spectrum', accent: 'choose', title: 'Load a VCF', badge: 'nothing to count',
                icon: 'upload_file', ready: true, blurb: 'Any callset with single-base substitutions.', open: () => uploadMenu() });
            books.push({ section: 'Back', title: 'Check the calls', badge: 'back', icon: 'arrow_back', back: true, ready: true,
                blurb: 'The other checks on what is loaded.', open: () => qcMenu() });
            exec('baja/lib/shelf.js', { id: 'baja-karyo-analysis', title: 'Mutational spectrum',
                subtitle: 'six substitution classes, per file' + (pair ? ' and for the somatic calls' : ''), graph: graph, books: books });
        };

        // ---- 4. CONCORDANCE: TWO CALLSETS, OR A CALLSET AGAINST A TRUTH SET -------------
        //
        // A variant is the same call when it is the same position and the same change. The
        // arrays are sorted by position, so each chromosome is one walk grouping equal
        // positions and comparing their alleles by side. With one side named the truth, the
        // counts become precision and recall -- with the caveat stated, because a truth set
        // like SEQC2's covers only its own confident regions, and a call outside them is not
        // wrong, just unjudged.
        const concRun = async (confOnly) => {
            clearWorking();
            qcClearHl();
            let both = 0, onlyL = 0, onlyR = 0, skipped = 0;
            const perChrom = [];
            for (let ci = 0; ci < drawn.length; ci++) {
                const d = vdata[ci];
                if (!d || !d.n || !d.side) continue;
                graph.setMessage(' Matching calls on ' + drawn[ci].name + '… ');
                let b0 = 0, l0 = 0, r0 = 0;
                let k = 0;
                while (k < d.n) {
                    let e = k;
                    while (e + 1 < d.n && d.pos[e + 1] === d.pos[k]) e++;
                    const L = new Map(), R = new Map();
                    for (let j = k; j <= e; j++) {
                        // A call its own caller failed is not a call to compare. MuTect2's
                        // unfiltered output is mostly those, and counted in they swamp
                        // every difference that matters.
                        if (confOnly && d.rconf && d.rconf[j] === CONF_LOW) { skipped++; continue; }
                        const ab = allelesAt(ci, j);
                        const key = ab[0] + '>' + ab[1];
                        (d.side[j] ? L : R).set(key, j);
                    }
                    for (const [key, j] of L) { if (R.has(key)) { both++; b0++; } else { onlyL++; l0++; d.hl[j] = HL_CONC_L; } }
                    for (const [key, j] of R) { if (!L.has(key)) { onlyR++; r0++; d.hl[j] = HL_CONC_R; } }
                    k = e + 1;
                }
                perChrom.push({ name: drawn[ci].name, both: b0, onlyL: l0, onlyR: r0 });
                await new Promise((r2) => setTimeout(r2, 0));
            }
            concResult = { both: both, onlyL: onlyL, onlyR: onlyR, perChrom: perChrom, confOnly: confOnly, skipped: skipped };
            graph.setMessage(' ' + both.toLocaleString() + ' shared, ' + onlyL.toLocaleString() + ' left only, ' + onlyR.toLocaleString() + ' right only. ');
            if (onlyL || onlyR) qcMarkAndShow(onlyL >= onlyR ? HL_CONC_L : HL_CONC_R); else legendRefresh();
            concMenu();
        };
        const concMenu = () => {
            try { if (typeof hideAllModal === 'function') hideAllModal(); } catch (e) { }
            const sc = sideCounts();
            const R = concResult;
            const books = [];
            books.push({ section: 'Compare two callsets', note: true,
                title: 'The file on the left against the file on the right: the calls both made, and the ones only one did. Two callers '
                    + 'run on the same sample, one aligner against another, or a callset against a truth set — the differences are '
                    + 'the method, because the biology is the same on both sides.' });
            if (!(sc.left && sc.right)) {
                books.push({ section: 'Compare two callsets', accent: 'choose', title: sc.total ? 'Load the second callset on the left' : 'Load two callsets',
                    badge: 'needs both sides', icon: 'upload_file', ready: true,
                    blurb: 'Upload asks which side a new file goes on. For SEQC2, any two of WGS_IL_1.bwa.muTect2, .strelka and .somaticSniper '
                        + 'compare callers on identical data; the high-confidence truth VCF on either side scores one against the truth.',
                    open: () => uploadMenu() });
            } else if (!R) {
                books.push({ section: sideName(1) + '  ↔  ' + sideName(0), accent: 'run', title: 'Calls that passed their filters',
                    badge: sc.left.toLocaleString() + ' · ' + sc.right.toLocaleString(), icon: 'compare_arrows', ready: true,
                    blurb: 'Match by position and change, leaving out what either caller itself failed (a FILTER flag, or QUAL under 10). The comparison that judges a caller.',
                    open: () => concRun(true) });
                books.push({ section: sideName(1) + '  ↔  ' + sideName(0), accent: 'run', title: 'Every call, filtered or not', badge: 'everything',
                    icon: 'compare_arrows', ready: true,
                    blurb: 'Includes the calls each caller rejected — for seeing what a filter removed.',
                    open: () => concRun(false) });
            } else {
                const tot = R.both + R.onlyL + R.onlyR;
                books.push({ section: 'Result', note: true, mono: true, title:
                      'in both                ' + R.both.toLocaleString() + '\n'
                    + 'only on the left       ' + R.onlyL.toLocaleString() + '   ' + sideName(1) + '\n'
                    + 'only on the right      ' + R.onlyR.toLocaleString() + '   ' + sideName(0) + '\n'
                    + 'agreement (Jaccard)    ' + (tot ? (100 * R.both / tot).toFixed(1) + '%' : '—')
                    + (R.confOnly ? '\nfailed calls, left out   ' + R.skipped.toLocaleString() : '') });
                // One side as the truth: precision of the other, and its recall of the truth.
                const score = (truthSide) => {
                    const truthN = R.both + (truthSide ? R.onlyL : R.onlyR);
                    const callN = R.both + (truthSide ? R.onlyR : R.onlyL);
                    const prec = callN ? R.both / callN : 0, rec = truthN ? R.both / truthN : 0;
                    const f1 = (prec + rec) ? 2 * prec * rec / (prec + rec) : 0;
                    return 'precision  ' + (100 * prec).toFixed(1) + '%   of ' + callN.toLocaleString() + ' calls, ' + R.both.toLocaleString() + ' are in the truth\n'
                        + 'recall     ' + (100 * rec).toFixed(1) + '%   of ' + truthN.toLocaleString() + ' true variants, ' + R.both.toLocaleString() + ' were called\n'
                        + 'F1         ' + (100 * f1).toFixed(1) + '%';
                };
                [1, 0].forEach((ts) => books.push({ section: 'Score one against the other', title: sideName(ts) + ' as the truth set',
                    badge: 'precision · recall', icon: 'verified', ready: true,
                    blurb: 'Treat ' + sideName(ts) + ' as correct and score ' + sideName(ts ? 0 : 1) + ' against it.',
                    books: () => [
                        { note: true, mono: true, title: score(ts) },
                        { note: true, title: 'A truth set like SEQC2’s high-confidence VCF covers only its own confident regions. A call outside '
                            + 'them lands in the false positives here without being wrong — it is unjudged — so precision reads lower than '
                            + 'a benchmark restricted to those regions would report.' },
                    ] }));
                R.perChrom.filter((c) => c.onlyL || c.onlyR).sort((a, b) => (b.onlyL + b.onlyR) - (a.onlyL + a.onlyR)).slice(0, 24)
                    .forEach((c) => books.push({ section: 'Where they differ most', title: c.name,
                        badge: c.onlyL.toLocaleString() + ' · ' + c.onlyR.toLocaleString(), icon: 'zoom_in', ready: true,
                        blurb: c.both.toLocaleString() + ' in both, ' + c.onlyL.toLocaleString() + ' only left, ' + c.onlyR.toLocaleString() + ' only right.',
                        open: () => { const ci = chromIndexOf(c.name); if (ci >= 0) goView({ x0: barLeft(ci) - 0.6 * SLOT, x1: barRight(ci) + 0.6 * SLOT, y0: wy(drawn[ci].length), y1: wy(0) }); } }));
                books.push({ section: 'Take it away', title: 'Run it again', badge: 'again', icon: 'refresh', ready: true,
                    blurb: 'After loading a different pair.', open: () => { concResult = null; concMenu(); } });
            }
            books.push({ section: 'Back', title: 'Check the calls', badge: 'back', icon: 'arrow_back', back: true, ready: true,
                blurb: 'The other checks on what is loaded.', open: () => qcMenu() });
            exec('baja/lib/shelf.js', { id: 'baja-karyo-analysis', title: 'Compare two callsets',
                subtitle: R ? (R.both.toLocaleString() + ' shared · ' + R.onlyL.toLocaleString() + ' left only · ' + R.onlyR.toLocaleString() + ' right only')
                    : 'what both found, and what only one did', graph: graph, books: books });
        };

        // ---- the door to all four -----------------------------------------------------
        const qcMenu = () => {
            try { if (typeof hideAllModal === 'function') hideAllModal(); } catch (e) { }
            const sc = sideCounts();
            const pairNamed = qcPairSpecs().some((x) => x.named);
            const anyReads = vdata.some((d) => d && d.baf);
            const books = [];
            books.push({ section: 'Check the calls', note: true,
                title: 'Before reasoning from a callset, how far to trust it. These read only what is loaded and re-call nothing: they '
                    + 'show where a file’s calls and its own reads disagree, what kind of changes it holds, and how it compares with another.' });
            books.push({ section: 'Check the calls', accent: 'run', title: 'Somatic calls the normal carries', icon: 'fact_check', ready: true,
                badge: nsupResult ? nsupResult.carried.toLocaleString() + ' flagged' : (SAMPLES.length >= 2 ? (pairNamed ? 'tumour · normal' : 'pick the normal') : 'needs a pair'),
                blurb: 'Calls the tumour carries that the normal’s own reads carry too: germline, contamination or a shared artefact, '
                    + 'whatever the genotype column says.', open: () => nsupMenu() });
            books.push({ section: 'Check the calls', accent: anyReads ? 'run' : undefined, title: 'Genotypes the reads contradict', icon: 'rule', ready: true,
                badge: gtReadResult ? gtReadResult.marked.toLocaleString() + ' marked' : (anyReads ? 'every sample' : 'needs read counts'),
                blurb: 'A 1/1 under 60% of the reads, a 0/1 over 95% — the calls whose genotype every genotype-based analysis would inherit.',
                open: () => gtReadMenu() });
            books.push({ section: 'Check the calls', accent: 'run', title: 'Mutational spectrum', icon: 'bar_chart', ready: true,
                badge: 'six classes', blurb: 'The substitution profile per file' + (pairNamed ? ', and for the somatic calls alone' : '') + '.',
                open: () => spectrumMenu() });
            books.push({ section: 'Check the calls', accent: (sc.left && sc.right) ? 'run' : 'choose', title: 'Compare two callsets', icon: 'compare_arrows', ready: true,
                badge: concResult ? (concResult.both.toLocaleString() + ' shared') : ((sc.left && sc.right) ? 'left ↔ right' : 'load a second file'),
                blurb: 'Two callers on the same sample, or a callset against a truth set: shared calls, calls only one found, precision and recall.',
                open: () => concMenu() });
            books.push({ section: 'Back', title: 'Analyze', badge: 'back', icon: 'arrow_back', back: true, ready: true,
                blurb: 'The losses, the differential, synthetic lethality and the rest.', open: () => analysisMenu() });
            exec('baja/lib/shelf.js', { id: 'baja-karyo-analysis', title: 'Check the calls',
                subtitle: 'how far to trust what is loaded', graph: graph, books: books });
        };
        // LABELLING WHAT IS LOADED. A VCF's sample column is called whatever the pipeline
        // called it -- "SAMPLE1", a barcode, a run id -- and two files are "the left one" and
        // "the right one". Anyone comparing a tumour with its normal needs to say which is
        // which, once, and have every panel, report and saved file follow. The name in the
        // file is kept (SAMPLE_VCF), so a label never stops a later file matching its slot.
        const labelSamplesDialog = () => {
            const esc4 = (t) => ('' + (t == null ? '' : t)).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
            const sc = sideCounts();
            const rows = [];
            for (let i = 0; i < SAMPLES.length; i++) rows.push({ kind: 'sample', i: i, was: SAMPLE_VCF[i] || SAMPLES[i], now: SAMPLES[i] });
            if (sc.right) rows.push({ kind: 'side', i: 0, was: sideFile[0] ? shortFile(sideFile[0]) : 'the file on the right', now: SIDE_LABEL[0] });
            if (sc.left) rows.push({ kind: 'side', i: 1, was: sideFile[1] ? shortFile(sideFile[1]) : 'the file on the left', now: SIDE_LABEL[1] });
            if (!rows.length) { graph.setMessage(' Load a VCF first: there is nothing to label. '); return; }
            try { const old = document.getElementById('baja-karyo-labels'); if (old && old.parentNode) old.parentNode.removeChild(old); } catch (e) { }
            const wrap = document.createElement('div');
            wrap.id = 'baja-karyo-labels';
            wrap.style.cssText = 'position:fixed;inset:0;z-index:2147483300;background:rgba(0,0,0,0.45);font-family:Arial,Helvetica,sans-serif;';
            const field = 'width:100%;box-sizing:border-box;background:#0a1e3a;color:#e8f0fb;border:1px solid rgba(255,255,255,0.16);border-radius:8px;padding:8px;font:13px Arial;';
            wrap.innerHTML = '<div style="position:absolute;top:70px;left:50%;transform:translateX(-50%);width:min(560px,94vw);max-height:calc(100vh - 110px);overflow:auto;'
                + 'background:#0b2545;color:#fff;border:1px solid rgba(255,255,255,0.14);border-radius:12px;box-shadow:0 12px 40px rgba(0,0,0,0.45);padding:18px;">'
                + '<div style="font:700 16px Arial;margin-bottom:4px;">Label what is loaded</div>'
                + '<div style="font:12px Arial;color:#9fb3c8;margin-bottom:14px;">The name you give is used everywhere -- the pills, the loss matrix, the differential, '
                + 'the LOH scan and its reports -- and is saved with the genome. The name inside the file is kept.</div>'
                + rows.map((rw, k) => '<div style="margin-bottom:12px;"><div style="font:12px Arial;color:#9fb3c8;margin-bottom:4px;">'
                    + (rw.kind === 'sample' ? 'Sample column <b style="color:#cfe0f5;">' + esc4(rw.was) + '</b>' : 'File: <b style="color:#cfe0f5;">' + esc4(rw.was) + '</b>')
                    + '</div><input id="kl-' + k + '" value="' + esc4(rw.now || '') + '" placeholder="' + esc4(rw.was) + '" style="' + field + '"/></div>').join('')
                + '<div style="margin-top:14px;display:flex;gap:10px;">'
                + '<button id="kl-save" style="cursor:pointer;border-radius:8px;padding:9px 16px;font:700 12.5px Arial;border:1px solid #22c55e;background:#22c55e;color:#04210f;">Use these names</button>'
                + '<button id="kl-reset" style="cursor:pointer;border-radius:8px;padding:9px 16px;font:700 12.5px Arial;border:1px solid rgba(255,255,255,0.22);background:transparent;color:#fff;">The names in the files</button>'
                + '<button id="kl-x" style="cursor:pointer;border-radius:8px;padding:9px 16px;font:700 12.5px Arial;border:1px solid rgba(255,255,255,0.22);background:transparent;color:#fff;">Cancel</button>'
                + '</div></div>';
            document.body.appendChild(wrap);
            for (const ev of ['paste', 'cut', 'copy', 'keydown', 'keyup', 'input']) wrap.addEventListener(ev, (e) => { try { e.stopPropagation(); } catch (e2) { } });
            const shut = () => { try { if (wrap.parentNode) wrap.parentNode.removeChild(wrap); } catch (e) { } };
            wrap.addEventListener('click', (e) => { if (e.target === wrap) shut(); });
            wrap.addEventListener('keydown', (e) => { if (e.key === 'Escape') shut(); });
            document.getElementById('kl-x').onclick = shut;
            const apply = (values) => {
                rows.forEach((rw, k) => {
                    const v = ('' + (values ? values[k] : '')).trim();
                    if (rw.kind === 'sample') SAMPLES[rw.i] = v || SAMPLE_VCF[rw.i] || SAMPLES[rw.i];
                    else SIDE_LABEL[rw.i] = v;
                });
                for (let si = 0; si < SAMPLES.length; si++) HL_NAME[SAMPLE_HL_BASE + si] = SAMPLES[si] || ('sample ' + (si + 1));
                shut();
                graph.setMessage(' The names are in use. They are saved with the genome. ');
            };
            document.getElementById('kl-save').onclick = () => apply(rows.map((rw, k) => (document.getElementById('kl-' + k) || {}).value || ''));
            document.getElementById('kl-reset').onclick = () => apply(rows.map(() => ''));
        };
        const analysisMenu = () => {
            try { if (typeof hideAllModal === 'function') hideAllModal(); } catch (e) { }
            // Back at the root, whatever errand was running is over: someone who came here
            // has left the workflow that sent them, and a "back to" card offering to return
            // to it an hour later is a promise about a state that no longer exists.
            selErrand = null;
            const nV = vtotal || vdata.reduce((a, d) => a + (d ? d.n : 0), 0);
            const books = [];
            // THE TOP-LEVEL WORKFLOWS COME FIRST, each one a door rather than a step.
            // Synthetic lethality leads because it is what the rest of this is FOR: the loss
            // matrix, the differential and the LOH scan are all ways of arriving at a set of
            // losses, and this is the question asked of that set. It is listed whether or not
            // anything is selected, because a menu that hides the destination until you have
            // already walked to it teaches nobody where they were going.
            // THE ORDER IS OUTWARD, from what is in front of you to what is furthest
            // from it: what this genome IS, then looking something up in it, then the two
            // analyses, with the deepest last. A library read top to bottom should get
            // further from the file with every section rather than jumping about.
            // FINDING A GENE COMES FIRST: it is what someone opening this library most often
            // wants, and it was below the analyses.
            books.push({ section: 'This genome', title: 'Find a gene, or act on the selected regions', badge: 'search', icon: 'search',
                blurb: 'Jump to a gene by name, see the genes inside the regions you have selected, and open their transcripts in the editor.',
                ready: true, open: () => { try { searchMenu(); } catch (e) { } } });
            books.push({ section: 'This genome', title: 'Label the samples and files', badge: SAMPLES.length ? String(SAMPLES.length) : '', icon: 'edit', ready: true,
                blurb: 'Give each VCF sample column and each loaded file the name you use for it -- "tumour", "the normal", "day 14" -- and every panel, report and saved file follows.',
                open: () => { try { labelSamplesDialog(); } catch (e) { } } });
            books.push({ section: 'This genome', title: 'What is loaded', badge: 'info', icon: 'info_outline',
                blurb: 'Variants, samples, regions, highlights and patents on this genome.', ready: true,
                open: () => { try { infoPanel(); } catch (e) { } } });
            // CLEARING WHAT IS SELECTED, where what is selected is described.
            //
            // Genes chosen for the model and regions dragged out on the chromosomes are two
            // different selections made in two different places, and both are cleared from
            // two different panels one level in. Someone who wants to start again wants
            // both gone at once, and Analyze is the one place that sees both.
            {
                const nSel = selGenes.size, nReg = (regions && regions.length) || 0;
                const parts = [];
                if (nSel) parts.push(nSel + ' gene' + (nSel === 1 ? '' : 's'));
                if (nReg) parts.push(nReg + ' region' + (nReg === 1 ? '' : 's'));
                books.push({ section: 'This genome', title: 'Deselect all', badge: parts.length ? parts.join(' \u00b7 ') : 'nothing selected',
                    icon: 'remove_done', ready: parts.length > 0, readyNote: 'nothing is selected',
                    blurb: parts.length
                        ? 'Clears ' + parts.join(' and ') + '. The variants, the loss matrix and every result are kept \u2014 this only undoes the choosing.'
                        : 'Clears the genes chosen for the model and the regions dragged out on the chromosomes. Nothing is chosen at the moment.',
                    open: () => {
                        try { selGenes.clear(); } catch (e) { }
                        try { regions = []; activeRegion = null; } catch (e) { }
                        try { reindexHighlights(); } catch (e) { }
                        try { legendRefresh(); } catch (e) { }
                        try { if (graph.wake) graph.wake(); } catch (e) { }
                        graph.setMessage(' Deselected ' + (parts.length ? parts.join(' and ') : 'nothing') + '. '
                            + 'The variants and every result are still here. ');
                        try { analysisMenu(); } catch (e) { }
                    } });
            }
            // THE LIST EVERYTHING ELSE READS, AT THE TOP LEVEL.
            //
            // Finding the genes this genome carries a damaging change in is not a step of
            // synthetic lethality, which is where it could only be reached from: it is the
            // first fact about a loaded file, and the compound-heterozygote check, the
            // allele-selective routes and the third-gene model all read it. Somebody who
            // wants to know what is broken in this genome should not have to walk into a
            // workflow about cell-line dependencies to ask.
            {
                const nVd = vtotal || vdata.reduce((a, d) => a + (d ? d.n : 0), 0);
                if (lossMatrix) {
                    const gsN = (lossMatrix.genes || []).length;
                    books.push({ section: 'This genome', title: 'Damaging variants', badge: gsN + ' gene' + (gsN === 1 ? '' : 's'),
                        icon: 'biotech', accent: 'run', ready: true,
                        blurb: lossMatrix.sample + ' \u2014 every gene with a loss-of-function change, tumor suppressors first, '
                            + 'with its zygosity, the filters and the download. This is the list the analyses below read.',
                        open: () => lossMatrixMenu() });
                } else {
                    books.push(Object.assign(lossCalcCard('This genome'), {
                        title: 'Find the damaging variants',
                        badge: nVd ? (SAMPLES.length > 1 ? SAMPLES.length + ' samples' : (SAMPLES[0] || 'all variants')) : 'load a VCF',
                        blurb: 'Reads every exonic variant on this genome and lists the genes carrying a loss-of-function change '
                            + '\u2014 the list the compound-heterozygote check, the allele-selective routes and the third-gene '
                            + 'model all reason from. About a minute on a whole genome.',
                    }));
                }
            }
            // HOW FAR TO TRUST WHAT IS LOADED, beside what it holds.
            // WHAT IS KNOWN TO CAUSE DISEASE, matched when the file loaded.
            {
                let nCv = 0;
                try { nCv = cvIdx.size ? cvMatches().length : 0; } catch (e) { }
                books.push({ section: 'This genome', title: 'ClinVar pathogenic variants', accent: nCv ? 'run' : undefined,
                    badge: nCv ? nCv.toLocaleString() + ' matched' : (cvEligible() ? 'matched on load' : 'human GRCh38'),
                    icon: 'coronavirus', ready: true,
                    blurb: 'The loaded variants ClinVar classifies as pathogenic or likely pathogenic, by exact allele: gene, condition, '
                        + 'review stars, genotype, and a way into each.',
                    open: () => cvMenu() });
            }
            books.push({ section: 'This genome', title: 'Check the calls', badge: 'quality · spectrum · compare',
                icon: 'fact_check', ready: true,
                blurb: 'Somatic calls the normal carries, genotypes the reads contradict, the mutational spectrum, and one callset '
                    + 'against another or against a truth set.',
                open: () => qcMenu() });
            // AFTER the whole of "This genome", not in the middle of it. The shelf heads a
            // RUN of cards that share a section, so a card from another section pushed between
            // them printed "This genome" twice, once above each piece.
            // THE TWO DIFFERENTIALS, WHERE THEY ARE LOOKED FOR. Both lived under "What is
            // loaded" — the panel that says what a file HAS, not what can be done with it —
            // so a panel people ask for by name was three steps away from Analyze.
            if (SAMPLES.length > 1 || (sideCounts().left && sideCounts().right)) {
                books.push({ section: 'What differs between two', title: 'Differential matrix',
                    badge: diffVarResult ? 'done · show' : 'the sites', icon: 'difference', accent: 'run', ready: true,
                    blurb: 'Every site the two samples do not share, damaging or not. An oligo tells two genomes apart '
                        + 'on sequence, so a silent change discriminates as well as a nonsense one — these are the sites '
                        + 'a selective design can be built on, and each one opens its gene as two tracks.',
                    open: () => diffVarMenu() });
                books.push({ section: 'What differs between two', title: 'Differential loss matrix',
                    badge: diffResult ? 'done · show' : 'pick the pair', icon: 'compare', accent: 'run', ready: true,
                    blurb: 'The narrower question: which GENES one of them has lost that the other has not, by '
                        + 'loss-of-function change. Genes there open as two tracks as well.',
                    open: () => { if (diffResult) diffMenu(); else exec('baja/lib/shelf.js', { id: 'baja-karyo-analysis', title: 'Differential loss matrix', subtitle: 'Choose the two to compare', graph: graph, books: diffPickerBooks() }); } });
            }
            // PATENTS ARE NOT LISTED HERE. The toolbar above the chromosomes has its own
            // Patents button, and the same switch in two places reads as two different things.
            // LOSS OF HETEROZYGOSITY, AT THE TOP. It was a step inside "Find the losses", two
            // levels down, though it answers its own question and now carries its own report.
            if (lohResult) {
                // ONE CARD, THE ONE THAT LEADS SOMEWHERE. The scan's own card and the PDF card
                // were listed beside it; the strategy is what the scan is for, and both of the
                // others are a step inside it -- the scan's results are still one press away,
                // under "Loss of heterozygosity" at the foot of the strategy's own chooser, and
                // the PDF is offered there too.
                const R0 = lohResult;
                books.push({ section: 'Loss of heterozygosity', title: 'LOH Design Strategy', icon: 'edit', badge: 'editor', accent: 'run',
                    ready: !lohReportBusy && !lohUiBusy, readyNote: 'a report is being built',
                    blurb: R0.spec.labelN + ' as the normal, ' + R0.spec.labelT + ' as the tumor. Every tumor suppressor, activating change and essential gene with its mutation, each one a button into the oligo editor.',
                    open: () => lohReportStart('ui') });
            } else {
                const ls = lohSpecs();
                books.push({ section: 'Loss of heterozygosity', title: 'Scan for loss of heterozygosity', icon: 'compress', accent: ls.length ? 'run' : 'choose',
                    badge: ls.length ? (ls.some((x) => x.kind === 'side') ? 'two files' : 'two samples') : 'needs a tumor and its normal', ready: true,
                    blurb: ls.length ? 'Sites the normal carries on two alleles and the tumor on one: the tracts, the genes inside them, second hits, activating changes the loss made homozygous, and a report.'
                        : 'Needs a tumor and its normal: two samples of one VCF, or a second file loaded on the left of the chromosomes.',
                    open: () => lohStart() });
            }
            {
                const nV2 = vtotal || vdata.reduce((a, d) => a + (d ? d.n : 0), 0);
                const nPh = asPhasedSamples().length;
                const ways = [(lohResult && lohResult.spec) ? 'somatic retention' : '', nPh ? 'phased germline' : '', nV2 ? 'the mutation itself' : ''].filter(Boolean);
                books.push({ section: 'Allele-selective targets', title: 'Find allele-selective targets',
                    badge: lohAlleleResult ? (lohAlleleResult.sites.length + ' sites') : (ways.length ? ways.length + ' of 3 ways' : 'sequence, not dose'),
                    icon: 'gps_fixed', ready: nV2 > 0, readyNote: 'load a VCF first',
                    blurb: 'Two copies that differ in SEQUENCE can be told apart by an oligo; two that differ only in '
                        + 'AMOUNT can only be dosed against. Three things can say which copy to hit — a tumor that kept '
                        + 'one allele, a phased disease haplotype, or the mutation itself — and only the first needs a '
                        + 'tumor. Run any of them over the whole genome, the genes or regions you have selected, or a '
                        + 'gene you name.'
                        + (ways.length ? ' Available on this data: ' + ways.join(', ') + '.' : ' Nothing is loaded yet.'),
                    open: () => alleleSelectiveMenu() });
            }
            {
                const done = [slResult && (slResult.targets.length + ' targets'),
                    hoResult && (hoResult.matched.length + ' in the catalogue'),
                    parResult && 'paralogs',
                    lohSlResult && (lohSlResult.cyclops.length + ' single-copy')].filter(Boolean);
                books.push({ section: 'Synthetic Lethality using Background Genetics', title: 'Synthetic Lethality using Background Genetics', icon: 'biotech',
                    badge: done.length ? done.join(' \u00b7 ') : (selGenes.size ? selWord() + ' selected' : BAJA3),
                    ready: true,
                    blurb: BAJA3_LONG + '. Which gene this tumor cannot survive losing, given what it has already '
                        + 'lost: the live DepMap screen, the published catalogue, the paralog model, and what the '
                        + 'loss of heterozygosity makes it depend on.'
                        + (selGenes.size ? '' : ' Needs a set of losses; the first card inside says how to get one.'),
                    open: () => synLethalMenu() });
            }
            exec('baja/lib/shelf.js', {
                id: 'baja-karyo-analysis', title: 'Analyze',
                subtitle: 'Read the loaded variants — the loss matrix, what differs between two, loss of heterozygosity, synthetic lethality and allele-selective targets',
                graph: graph, books: books
            });
        };

        // ---- CLICKING ONE VARIANT ------------------------------------------------
        //
        // Only when the view can actually separate them. Zoomed out, a pixel column is
        // tens of thousands of bases and a click would be a guess dressed up as an
        // answer; so a variant is clickable when it sits within CLICK_PX of the
        // pointer AND its nearest neighbour is at least SEPARATE_PX away, which is the
        // same thing as saying the marks are far enough apart to be aimed at.
        const CLICK_PX = 6;
        const SEPARATE_PX = 5;
        // A SELECTED REGION, IF THE POINTER IS ON ITS BAND.
        //
        // The callout card is only drawn when a region is too small to label where it is --
        // which is to say when the view is zoomed OUT. Zoomed in there is no card, and the
        // region itself was not clickable, so the menu could only be reached by framing the
        // whole genome first. The band is the region; clicking it should open what the card
        // opens.
        //
        // Tested LAST, after the variants and marks that sit on the same bar: a click on a
        // variant is a click on that variant, not on the region it happens to lie in.
        // A CLICK TARGET NO SMALLER THAN WHAT IS DRAWN.
        //
        // The band is drawn at `Math.max(1.5, ...)` px tall plus a stroke either side, so a
        // gene always LOOKS clickable. This test had no such floor: it compared base pairs,
        // and at the framing this view opens in -- the whole genome, ~509,000 bases to the
        // pixel -- a highlighted BRCA1 is a band 0.25 px tall and TP53 is 0.05 px. Clicking
        // the thing you can plainly see missed it essentially every time, and since a region
        // is the last thing the click dispatch tries, the press did nothing at all: no menu,
        // no editor, no message saying why.
        //
        // So the test is padded by the same pixels the drawing rounds up to, converted to
        // bases through the grid's own scale. Zoomed in, where a region is already hundreds
        // of pixels tall, the padding is a few hundred bases and changes nothing.
        const REGION_GRAB_PX = 3;
        const regionAt = (wx, wyy) => {
            const bp = -wyy * MB;
            const pad = Math.max(0, (basesPerPx() || 0) * REGION_GRAB_PX);
            for (let q = regions.length - 1; q >= 0; q--) {
                const rg = regions[q];
                const c = drawn[rg.i];
                if (!c || c.circular) continue;
                if (wx < barLeft(rg.i) || wx > barRight(rg.i)) continue;
                if (bp < rg.lo - pad || bp > rg.hi + pad) continue;
                return rg;
            }
            return null;
        };

        // A PATENT LABEL, IF THE POINTER IS ON ONE. Screen pixels: the labels are laid out
        // against the bar's width on screen, not against the genome.
        const patLabelAt = (px, py) => {
            for (const l of patLabelHits) {
                if (px >= l.x && px <= l.x + l.w && py >= l.y && py <= l.y + l.h) return l;
            }
            return null;
        };
        // The publication itself. Google Patents rather than a panel of our own: the thing
        // a reader wants from a patent number is the patent, and we hold nothing about it
        // that its own record does not say better.
        const patOpenPublication = (l) => {
            const id = ('' + ((l && l.id) || '')).replace(/[^0-9A-Za-z]/g, '');
            if (!id) { graph.setMessage(' That label carries no publication number. '); return; }
            const url = 'https://patents.google.com/patent/US' + id;
            graph.setMessage(' Opening US' + id + '… ');
            try { window.open(url, '_blank', 'noopener'); }
            catch (e) {
                graph.setMessage(' Could not open ' + url + ' — the browser blocked it. ');
            }
        };

        // ONE PATENT AS A LIBRARY. Clicking a patent label opens this shelf: the record
        // (number, assignee, title, filing/grant dates, how much sequence it claims and
        // where) as prose, then a leaf that opens the publication itself. Built as `books`
        // so it can be shown on its own OR drilled into from the cluster shelf below, with a
        // Back either way.
        const patentDetailBooks = (p, where) => {
            const num = ('' + (p.label || ('US' + (p.id || '')))).split(' ')[0];
            const assignee = p.assignee
                || ('' + (p.label || '')).split(' ').slice(1).join(' ');
            const books = [];
            if (p.title) books.push({ section: 'Patent', note: true, blurb: p.title });
            books.push({ section: 'Patent', note: true, blurb: 'Publication  ·  ' + num });
            if (assignee) books.push({ note: true, blurb: 'Assignee  ·  ' + assignee });
            if (p.filed) books.push({ note: true, blurb: 'Filed  ·  ' + p.filed });
            if (p.granted) books.push({ note: true, blurb: 'Granted  ·  ' + p.granted });
            if (p.hits != null && p.hits !== '') {
                books.push({
                    note: true, blurb: (+p.hits).toLocaleString() + ' sequence hit' + ((+p.hits) === 1 ? '' : 's')
                        + (p.transcripts ? ' over ' + p.transcripts + ' transcript' + ((+p.transcripts) === 1 ? '' : 's') : '')
                });
            }
            if (where) books.push({ note: true, blurb: 'Location  ·  ' + where });
            books.push({
                section: 'Open', title: 'Open on Google Patents', icon: '↗',
                blurb: 'The full publication — claims, description, and patent family — on patents.google.com.',
                open: () => patOpenPublication({ id: p.id }),
            });
            return books;
        };
        const patentInfoOne = (p, where) => {
            const num = ('' + (p.label || ('US' + (p.id || '')))).split(' ')[0];
            const assignee = p.assignee || ('' + (p.label || '')).split(' ').slice(1).join(' ');
            try {
                exec('baja/lib/shelf.js', {
                    id: 'baja-patent-info',
                    title: num + (assignee ? '  —  ' + assignee : ''),
                    subtitle: p.title || 'Patent record',
                    books: patentDetailBooks(p, where),
                    graph: graph,
                });
            } catch (e) { graph.setMessage(' The patent library could not open: ' + (e && e.message ? e.message : e) + ' '); }
        };
        // SEVERAL PATENTS (a summary label) AS A LIBRARY. Fetches the list for the stretch
        // and shows one card per patent; each drills into its own record shelf above.
        const patentInfoCluster = async (h) => {
            const c = drawn[h.ci];
            const where = c.name + ':' + human(h.lo) + '-' + human(h.hi);
            graph.setMessage(' Reading the patents over ' + where + '… ');
            let rs = null;
            try {
                const em = new EngineMonitor((m) => { try { graph.setMessage(' ' + m + ' '); } catch (e) { } });
                rs = await exec(server + '/py/bio/patents-at.py', em,
                    c.name.replace(/^chr/, ''), String(h.lo), String(h.hi),
                    PAT_NAME_KEY, (r.species || 'human'), '200');
            } catch (e) { rs = null; step('patents-at (cluster) threw: ' + e); }
            if (!rs || !rs.ok) { graph.setMessage(' The patents there could not be read. '); return; }
            let list = [];
            try { list = JSON.parse(rs.patents || '[]'); } catch (e) { list = []; }
            const heading = (rs.count || list.length) + ' patent' + ((rs.count || list.length) === 1 ? '' : 's') + ' over ' + where;
            const books = list.map((p) => {
                const num = ('' + (p.label || ('US' + (p.id || '')))).split(' ')[0];
                const assignee = p.assignee || ('' + (p.label || '')).split(' ').slice(1).join(' ');
                return {
                    section: heading,
                    title: num + (assignee ? '  —  ' + assignee : ''),
                    blurb: p.title || '',
                    badge: (p.hits != null && p.hits !== '') ? ((+p.hits) + ' hit' + ((+p.hits) === 1 ? '' : 's')) : '',
                    books: () => patentDetailBooks(p, where),
                };
            });
            if (!books.length) books.push({ note: true, blurb: 'No named patent claims sequence here.' });
            if ((rs.count || 0) > list.length) {
                books.push({ note: true, blurb: (rs.count - list.length) + ' further patents claim sequence here; the busiest ' + list.length + ' are listed.' });
            }
            try {
                exec('baja/lib/shelf.js', {
                    id: 'baja-patent-info',
                    title: 'Patents over ' + where,
                    subtitle: (rs.hits || 0).toLocaleString() + ' sequence hits in this window',
                    books: books,
                    graph: graph,
                });
            } catch (e) { graph.setMessage(' The patent library could not open: ' + (e && e.message ? e.message : e) + ' '); }
        };

        // THE PATENT STRIP, IF THE POINTER IS ON IT. It is drawn in the gutter to the LEFT
        // of a bar, where nothing else is, so this can never take a click meant for a
        // variant mark or a gene label -- those are all on the right.
        const PAT_GUTTER_PX = 30;       // 2 + maxW, and maxW tops out at 26
        const patAt = (wx, wyy) => {
            if (!patOn || !patHist) return null;
            const wppX = worldPerPxX();
            if (!(wppX > 0)) return null;
            const gut = PAT_GUTTER_PX * wppX;
            const slot = Math.floor(wx / SLOT);
            for (const i of [slot, slot + 1]) {
                if (i < 0 || i >= drawn.length) continue;
                const c = drawn[i];
                if (c.circular || !patHist[i]) continue;
                if (wx > barLeft(i) + 2 * wppX || wx < barLeft(i) - gut) continue;
                const bp = -wyy * MB;
                if (bp < 0 || bp > c.length) continue;
                const scale = HIST_BINS / c.length;
                let b = (bp * scale) | 0;
                if (b < 0) b = 0;
                if (b >= HIST_BINS) b = HIST_BINS - 1;
                if (!patHist[i][b]) continue;      // an empty bin has nothing to open
                return {
                    ci: i, bin: b, n: patHist[i][b],
                    lo: Math.max(1, Math.floor(b / scale)),
                    hi: Math.min(c.length, Math.ceil((b + 1) / scale)),
                };
            }
            return null;
        };

        // What claims sequence in that bin, as a panel.
        const patOpen = async (h) => {
            const c = drawn[h.ci];
            const where = c.name + ':' + human(h.lo) + '-' + human(h.hi);
            graph.setMessage(' Reading the patents over ' + where + '… ');
            let rs = null;
            try {
                const em = new EngineMonitor((m) => { try { graph.setMessage(' ' + m + ' '); } catch (e) { } });
                rs = await exec(server + '/py/bio/patents-at.py', em,
                    c.name.replace(/^chr/, ''), String(h.lo), String(h.hi),
                    PAT_NAME_KEY, (r.species || 'human'), '60');
            } catch (e) { rs = null; step('patents-at threw: ' + e); }
            if (!rs || !rs.ok) {
                graph.setMessage(' The patents there could not be read'
                    + ((rs && rs.error) ? (': ' + rs.error) : '') + '. ');
                return;
            }
            let list = [];
            try { list = JSON.parse(rs.patents || '[]'); } catch (e) { list = []; }
            const sections = [];
            if (!list.length) {
                sections.push({
                    heading: 'Nothing claimed here',
                    text: 'No patent in this set claims sequence over the transcripts in this '
                        + 'window. The strip is drawn from transcript midpoints, so a bin can '
                        + 'be tall because of a gene whose body starts outside the window.',
                });
            } else {
                sections.push({
                    heading: (rs.count || list.length) + ' patent'
                        + ((rs.count || list.length) === 1 ? '' : 's'),
                    text: list.map((pp) => pp.label + '  —  ' + pp.hits + ' hit'
                        + (pp.hits === 1 ? '' : 's') + ' over ' + pp.transcripts + ' transcript'
                        + (pp.transcripts === 1 ? '' : 's')).join('\n'),
                });
                if ((rs.count || 0) > list.length) {
                    sections.push({
                        heading: 'Not listed',
                        text: ((rs.count - list.length) + ' further patents claim sequence here; '
                            + 'the busiest ' + list.length + ' are shown.'),
                    });
                }
            }
            sections.push({
                heading: 'What was searched',
                text: 'The named patents come from the ASO/siRNA set, matched through the '
                    + (rs.transcripts || 0) + ' transcript'
                    + ((rs.transcripts || 0) === 1 ? '' : 's') + ' overlapping this window. '
                    + 'The strip itself is drawn from the larger 2020-2025 index, which '
                    + 'carries no patent numbers — so the bar height and this list are '
                    + 'measuring different collections and will not add up.\n\n'
                    + 'A hit is claimed SEQUENCE, not a claim over the gene.',
            });
            try {
                await exec('baja/lib/model-panel.js', {
                    id: 'baja-patents-at',
                    title: 'Patents over ' + where,
                    subtitle: (rs.hits || 0).toLocaleString() + ' sequence hits in this window',
                    cards: [{ title: where, meta: c.name + '  ·  ' + fmtSpan(h.hi - h.lo + 1)
                        + '  ·  ' + Math.round(h.n).toLocaleString() + ' hits in this bin',
                        sections: sections }],
                });
            } catch (e) {
                graph.setMessage(' The patent panel could not open: '
                    + (e && e.message ? e.message : e) + ' ');
            }
        };

        // A CARD, IF THE POINTER IS ON ONE. Screen pixels, because that is the space the
        // cards are laid out in -- they are pinned to the margin, not to the genome.
        const calloutAt = (px, py) => {
            for (const c of calloutHits) {
                if (px >= c.x && px <= c.x + c.w && py >= c.y && py <= c.y + c.h) return c;
            }
            return null;
        };

        // ---- CLICKING A MARK --------------------------------------------------------
        //
        // While a filter is on, every matching variant carries a mark in the gutter just
        // right of its chromosome: a magenta triangle each while few enough are in view, a
        // magenta spike per histogram bin when there are too many to place. Both say the
        // same thing -- something you asked for is HERE -- and the next question is always
        // the same one: what is it in? So the marks are the way in to the transcripts.
        //
        // This is deliberately NOT variantAt. That one refuses unless the view can tell two
        // variants apart, which is right for "show me this SNP" and wrong here: the marks
        // are legible across the whole genome, and a click on one at genome zoom means the
        // place, not a particular base.
        const MARK_GUTTER_PX = 16;   // triangles reach ~12 px past the bar; spikes a little more
        const MARK_TOL_PX = 7;       // how near the pointer must be, down the chromosome
        const markAt = (wx, wyy) => {
            if (!hlActive) return null;                    // no marks drawn, nothing to hit
            const wppX = worldPerPxX(), bpp = basesPerPx();
            if (!(wppX > 0) || !(bpp > 0)) return null;
            const gut = MARK_GUTTER_PX * wppX;
            // The gutter sits right of barRight, which at a wide enough zoom crosses into
            // the next slot -- so the slot the pointer is in and the one before it are both
            // candidates, and the bar edge decides.
            const slot = Math.floor(wx / SLOT);
            for (const i of [slot, slot - 1, slot + 1]) {
                if (i < 0 || i >= drawn.length) continue;
                const c = drawn[i];
                if (c.circular) continue;
                const d = vdata[i];
                if (!d || !d.n || !d.hlIdx || !d.hlIdx.length) continue;
                // Two gutters now: the right one holds the marks loaded to the right, the
                // left one those loaded to the left. Which gutter the pointer is in says
                // which side's marks are candidates.
                let side = -1;
                if (wx >= barRight(i) - 2 * wppX && wx <= barRight(i) + gut) side = 0;
                else if (wx >= barLeft(i) - gut && wx <= barLeft(i) + 2 * wppX) side = 1;
                if (side < 0) continue;
                if (side ? !d.nL : (d.n === d.nL)) continue;
                const pbp = -wyy * MB;
                // hlIdx is ascending in k and therefore in position, so the same bisection
                // the drawing uses finds the mark nearest the pointer; the few entries
                // either side of it are checked for one on the right side of the bar.
                const idx = d.hlIdx;
                let a = 0, z = idx.length;
                while (a < z) { const m = (a + z) >> 1; if (d.pos[idx[m]] < pbp) a = m + 1; else z = m; }
                let best = -1, bestD = Infinity;
                for (let q = a - 4; q <= a + 3; q++) {
                    if (q < 0 || q >= idx.length) continue;
                    if ((d.side ? d.side[idx[q]] : 0) !== side) continue;
                    const dist = Math.abs(d.pos[idx[q]] - pbp);
                    if (dist < bestD) { bestD = dist; best = idx[q]; }
                }
                if (best < 0) continue;
                // Tolerance in PIXELS, so it is the same aim at every zoom: 7 px is 7 px
                // whether that is two megabases or two bases.
                if (bestD / bpp > MARK_TOL_PX) continue;
                return { ci: i, k: best, bp: d.pos[best] };
            }
            return null;
        };

        const variantAt = (wx, wyy) => {
            const h = at(wx, wyy);
            if (!h || h.circular) return null;
            const d = vdata[h.i];
            if (!d || !d.n) return null;
            // Bases per pixel, read off the grid's own scale rather than assumed from a
            // zoom level.
            const bpp = basesPerPx();
            if (!(bpp > 0)) return null;
            const p = -wyy * MB;
            // Nearest position, by bisection, then the better of the two neighbours.
            let a = 0, z = d.n;
            while (a < z) { const m = (a + z) >> 1; if (d.pos[m] < p) a = m + 1; else z = m; }
            let best = -1, bestD = Infinity, second = Infinity;
            for (const k of [a - 1, a, a + 1]) {
                if (k < 0 || k >= d.n) continue;
                const dist = Math.abs(d.pos[k] - p);
                if (dist < bestD) { second = bestD; bestD = dist; best = k; }
                else if (dist < second) { second = dist; }
            }
            if (best < 0) return null;
            if (bestD / bpp > CLICK_PX) return null;
            // Too crowded to aim at: say nothing rather than open the wrong one.
            if (isFinite(second) && (second - bestD) / bpp < SEPARATE_PX) return null;
            return { ci: h.i, k: best };
        };

        const SIG_NAME = ['', 'Pathogenic / likely pathogenic', 'Benign',
            'Uncertain significance', 'Conflicting classifications'];

        // ---- ONE VARIANT, AS A LIBRARY -----------------------------------------
        //
        // A click on a mark used to raise a small read-only card: change, name, ClinVar,
        // gene. Everything it said was worth saying and none of it could be ACTED on, so the
        // one thing a person wants after reading "BRCA1, pathogenic" -- to open it and work
        // on it -- meant closing the card, finding the gene again, dragging a region round
        // it and going through the transcript panel.
        //
        // So it is a shelf, in the idiom the rest of this view now uses: what is known about
        // the variant as notes, and underneath them the things that can be done with it. The
        // gene is looked up BEFORE the shelf opens rather than filled in after, because it is
        // a one-base query answering in a fifth of a second and it is what the buttons under
        // it have to name.
        // A CALL THAT SPEAKS ONCE AND THEN THINKS reads as a call that has died. The server
        // tools narrate their steps, but the gaps between those steps are several seconds of
        // nothing, and a line that has not changed is the same thing on screen as a line that
        // has stopped. This keeps the elapsed count moving under whatever was last said, so
        // the only question left -- is it still going -- is answered without asking.
        const workBeat = (base, sink) => {
            const at = Date.now();
            let t = null, last = base;
            const write = sink || ((m) => { try { graph.setMessage(' ' + m + ' '); } catch (e) { } });
            const draw = () => {
                const secs = Math.round((Date.now() - at) / 1000);
                try { write(last + (secs >= 3 ? '   ' + secs + 's' : '')); } catch (e) { }
            };
            draw();
            try { t = setInterval(draw, 1000); } catch (e) { }
            return { say: (m) => { if (m) { last = ('' + m).replace(/[.\u2026\s]+$/, ''); draw(); } },
                stop: () => { try { if (t) clearInterval(t); } catch (e) { } t = null; } };
        };
        const showVariant = async (ci, k) => {
            const c = drawn[ci], d = vdata[ci];
            const ab = allelesAt(ci, k);
            const pos = d.pos[k];
            const bare = c.name.replace(/^chr/, '');
            const nm = (d.names && d.names[k]) || '';
            const sig = SIG_NAME[d.cls[k]] || '';
            const mark = (d.hl && d.hl[k]) ? HL_NAME[d.hl[k]] : '';
            const where = c.name + ':' + human(pos);
            const change = ab[0] + ' \u2192 ' + ab[1];
            step('variant clicked ' + where);
            graph.setMessage(' ' + where + ' — reading the gene there… ');

            let gs = [];
            try {
                const em4 = new EngineMonitor(() => { });
                const rs = await exec(server + '/py/bio/genes-in-range.py', em4,
                    bare, '' + pos, '' + pos, (r.species || 'human'), '8');
                try { gs = JSON.parse((rs && rs.genes) || '[]'); } catch (e) { gs = []; }
            } catch (e) { step('gene lookup threw: ' + e); }
            const withTx = gs.filter((gn) => gn.transcript);
            const coding = withTx.filter((gn) => gn.coding);
            const lead = coding[0] || withTx[0] || gs[0] || null;
            const geneWord = lead ? (lead.gene || '') : '';

            const books = [];
            const note = (title, blurb) => { if (blurb) books.push({ section: 'This variant', note: true, title: title, blurb: blurb }); };
            note('change', 'Change: ' + change + (nm ? '   ·   ' + nm : ''));
            const cvi = (() => { try { return cvRowAt(ci, k); } catch (e) { return -1; } })();
            const cvR = cvi >= 0 ? cvRecord(ci, cvi) : null;
            if (cvR) note('clinvar', cvLine(cvR));
            else if (sig) note('significance', 'ClinVar: ' + sig);
            if (mark) note('marked', 'Marked by the current filter as ' + mark + '.');
            const gl = genotypesOf(d, k).filter((g) => g[1]);
            if (gl.length) {
                note('samples', 'Samples: ' + gl.map((g) => g[0] + ' ' + (GT_TEXT[g[1]] || './.')
                    + (g[1] >= GT_HET && PHASE_NAME[PHASE_OF_CODE[g[1]]]
                        ? ' (' + PHASE_NAME[PHASE_OF_CODE[g[1]]] + ')' : '')).join(',   '));
            }
            note('gene', gs.length
                ? ('Gene: ' + gs.slice(0, 4).map((gg) => (gg.gene || '?')
                    + (gg.biotype ? ' (' + gg.biotype + ')' : '')
                    + (gg.transcript ? ' ' + gg.transcript : '')).join(',   '))
                : 'No gene is annotated at this position.');
            note('place', where + '   ·   ' + c.name + ' is ' + human(c.length) + ' bp');

            // THE THING TO DO WITH IT. Straight through: the transcripts that contain this
            // base are the answer to "which transcript", so it does not ask. The variants
            // that come across are the ones inside those genes, not just this one, because a
            // change is read against its neighbours -- and then the view goes to THIS one.
            books.push({
                section: 'Open it',
                title: 'Open in oligo editor' + (geneWord ? ' — ' + geneWord : ''),
                badge: coding.length ? 'coding' : (withTx.length ? 'transcript' : 'nothing here'),
                ready: withTx.length > 0,
                readyNote: 'Nothing at this position has a transcript in the ' + (r.species || 'human')
                    + ' annotation, so there is nothing to load.',
                blurb: withTx.length
                    ? ('Load ' + (coding.length ? coding.slice(0, 6).map((g) => g.transcript).join(', ')
                        : withTx.slice(0, 6).map((g) => g.transcript).join(', '))
                        + ' into the editor with the variants that fall inside '
                        + (geneWord || 'it') + ', then go straight to this change.')
                    : '',
                open: async () => {
                    await openRange(ci, Math.max(0, pos - 1), Math.min(c.length, pos + 1), pos,
                        { focus: { chr: bare, pos: pos } });
                },
            });
            books.push({
                section: 'Open it',
                title: 'Select this region',
                badge: 'region',
                blurb: 'Add the gene around this variant to the selection, so it can be acted '
                    + 'on with the others rather than on its own.',
                open: async () => {
                    const lo2 = lead ? Math.max(0, +lead.start) : Math.max(0, pos - 1000);
                    const hi2 = lead ? Math.min(c.length, +lead.end) : Math.min(c.length, pos + 1000);
                    regions.push({ i: ci, lo: lo2, hi: hi2, label: (geneWord || where) + '  ' + change, gene: geneWord });
                    if (graph.wake) graph.wake();
                    graph.setMessage(' ' + (geneWord || where) + ' selected — region ' + regions.length + '. ');
                },
            });
            books.push({
                section: 'Open it',
                title: 'Zoom into it',
                badge: 'view', icon: 'zoom_in', ready: true,
                blurb: 'Frame this base on ' + c.name + ', close enough to read what is around it.',
                open: () => {
                    try {
                        const pad = Math.max((lead ? (+lead.end - +lead.start) : 4000) * 0.6, 4000) / MB;
                        goView({ x0: barLeft(ci) - 0.5 * SLOT, x1: barRight(ci) + 0.5 * SLOT,
                            y0: wy(pos) - pad, y1: wy(pos) + pad });
                    } catch (e) { }
                },
            });
            books.push({
                section: 'Open it',
                title: 'Download this variant',
                badge: 'csv', icon: 'file_download', ready: true,
                blurb: 'One row: position, alleles, significance and its name.',
                open: () => {
                    try {
                        dlSaveText(dlToCSV([dlVariantRow(ci, k)]), dlSafe(dlSpecies() + '_' + where.replace(/[:]/g, '_')) + '.csv', 'text/csv');
                        dlMsg('Downloaded.');
                    } catch (e) { dlErr('Could not build the CSV: ' + (e && e.message ? e.message : e)); }
                },
            });
            // TAKING ONE MARK OFF. The file on disk is not touched -- this is the drawing,
            // not the data -- and a reload or a fresh load brings it back, which is why it
            // does not ask first. Matching on the index rather than the position removes
            // exactly this mark and leaves any other change at the same base alone.
            books.push({
                section: 'Open it',
                title: 'Delete this variant',
                badge: 'takes it off', icon: 'delete_outline', ready: true,
                blurb: 'Remove this mark from the genome. Only this one goes; the file it came from is untouched.',
                open: () => {
                    try {
                        rebuildKeeping((ci2, pos2, k2) => !(ci2 === ci && k2 === k), 'removed ' + where);
                        graph.setMessage(' ' + where + ' ' + change + ' removed \u2014 '
                            + vtotal.toLocaleString() + ' variant' + (vtotal === 1 ? '' : 's') + ' left. ');
                    } catch (e) { graph.setError(' That could not be removed: ' + (e && e.message ? e.message : e) + ' ', 8); }
                },
            });
            if (cvR && cvR.vid) books.push({ section: 'Read about it', title: 'Open its ClinVar record', badge: cvR.short + ' ' + cvStars(cvR.stars),
                icon: 'link', ready: true, blurb: cvR.gene + (cvR.cond ? ' \u2014 ' + cvR.cond : '') + '. VariationID ' + cvR.vid + ', at NCBI.',
                open: () => { try { window.open(cvUrl(cvR.vid), '_blank', 'noopener'); } catch (e) { } } });
            // WHAT IS KNOWN ABOUT IT, asked for only when asked for: it is a model call and
            // most clicks on a mark are not a request for a dossier.
            books.push({
                section: 'Read about it',
                title: 'What is known about this variant',
                badge: 'dossier',
                blurb: 'Ask for a written summary under fixed headings: what the change is, how '
                    + 'it was classified, the conditions it is seen in, and what is not established.',
                books: async () => {
                    const beat = workBeat('Reading up on ' + (nm || where));
                    let out = [];
                    try {
                        const em5 = new EngineMonitor((m) => { try { beat.say(m); } catch (e) { } });
                        const rs = await exec(server + '/py/bio/variant-dossier.py', em5, JSON.stringify([{
                            key: where, name: nm || where, gene: geneWord, chr: bare, pos: pos,
                            ref: ab[0], alt: ab[1],
                            type: (ab[1].length > ab[0].length ? 'ins' : (ab[0].length > ab[1].length ? 'del' : 'snp')),
                            rsid: /^rs\d+$/i.test(nm) ? nm : '', clinsig: sig, clindn: '',
                            consequence: mark || '', transcript: lead ? (lead.transcript || '') : '',
                            annotations: [],
                        }]));
                        let vs = [];
                        try { vs = JSON.parse((rs && rs.variants) || '[]'); } catch (e) { vs = []; }
                        const one = vs[0];
                        if (rs && rs.error) {
                            out = [{ note: true, title: 'error', blurb: '' + rs.error }];
                        } else if (one && one.sections && one.sections.length) {
                            out = one.sections.map((sc) => ({
                                note: true, title: sc.heading || '',
                                blurb: (sc.heading ? sc.heading + ': ' : '') + (sc.text || ''),
                            }));
                        }
                    } catch (e) {
                        out = [{ note: true, title: 'error', blurb: 'That could not be read: ' + (e && e.message ? e.message : e) }];
                    }
                    beat.stop();
                    if (!out.length) out = [{ note: true, title: 'nothing', blurb: 'Nothing came back for this variant.' }];
                    return out;
                },
            });

            try {
                await exec('baja/lib/shelf.js', {
                    id: 'baja-variant-actions',
                    title: (nm ? nm + '  ·  ' : '') + where,
                    subtitle: change + (sig ? '   ·   ' + sig : '')
                        + (geneWord ? '   ·   ' + geneWord : ''),
                    graph: graph,
                    books: books,
                });
            } catch (e) { step('variant shelf failed: ' + e); }
        };

        // ---- the library of things to do with them ------------------------------
        // ---- FIND A GENE BY NAME ------------------------------------------------
        //
        // Everything else here starts from a place on the screen: drag a range, click a
        // mark. But nobody thinks in coordinates -- they think "where is SOD1" -- and
        // without this the only way to reach a gene is to know its megabase and drag to it.
        //
        // TWO LOOKUPS, because neither alone answers it. gene-locus.py reads the same
        // GENCODE annotation the rest of this view reads, so the span it returns is the
        // one the region will be drawn from -- but GENCODE gene rows carry no synonyms, so
        // it cannot resolve an old name. /gene-lookup can: it is the symbol table the
        // paste-gene-symbols tool uses, and it knows ALS1 is SOD1. So the symbol is tried
        // against the annotation first, and only what fails there is sent to /gene-lookup
        // to be translated into a stable id and asked again.
        const findGene = async (raw) => {
            const txt = ('' + (raw || '')).trim();
            // A TYPEAHEAD PICK IS A WHOLE ROW, not a word. The suggestion list joins the
            // fields it was given with commas -- "SOD1, ALS1, superoxide dismutase 1 […],
            // ENSG00000142168" -- and that string is what lands in the box. The stable id
            // in it is the unambiguous part, so it is preferred when present; otherwise the
            // first field, which is the symbol, is what was typed or picked.
            const ens = txt.match(/ENSG\d+/i);
            const sym = ens ? ens[0]
                : txt.replace(/[\r\n,;]+/g, ' ').split(' ').filter(Boolean)[0] || '';
            if (!sym) { graph.setMessage(' Type a gene symbol. '); return null; }
            const em = new EngineMonitor((m) => { try { log(m); graph.setMessage(' ' + m + ' '); } catch (e) { } });
            // WHICH GENOME WAS ACTUALLY SEARCHED. gene-locus.py echoes the species it
            // resolved the name to, and that is checked rather than assumed: it used to fall
            // back to the human annotation for any name it did not recognise, so a mouse
            // karyotype asking for Sod1 was answered with the human locus and no error --
            // an answer that looks like an answer and is about the wrong animal. It refuses
            // now, but a stale server would not, so the caller verifies.
            let searched = '';
            let lastError = '';
            const ask = async (key) => {
                let res = null;
                try {
                    res = await exec(server + '/py/bio/gene-locus.py', em, key,
                        (r.species || 'human'), '12');
                } catch (e) { return []; }
                if (!res || res.error) {
                    if (res && res.error) step('gene-locus: ' + res.error);
                    if (res && res.error) lastError = '' + res.error;
                    return [];
                }
                searched = '' + (res.species || '');
                const want = ('' + (r.species || 'human')).toLowerCase();
                if (searched && want.indexOf(searched.toLowerCase()) < 0
                    && searched.toLowerCase().indexOf(want) < 0) {
                    step('gene-locus searched ' + searched + ' but this genome is ' + want);
                    graph.setMessage(' That lookup searched the ' + searched + ' genome, not '
                        + want + '. Ignoring the result. ');
                    return [];
                }
                try { return JSON.parse(res.genes || '[]'); } catch (e) { return []; }
            };
            graph.setMessage(' Looking for ' + sym + '… ');
            let hits = await ask(sym);
            // THE SYNONYM TABLE IS HUMAN ONLY, so it is only consulted for a human
            // karyotype. /gene-lookup is an Ensembl symbol export whose every row carries an
            // ENSG id -- human. Asking it to translate a symbol for a mouse or yeast
            // karyotype returns a HUMAN gene id, which is then looked up in the mouse or
            // yeast annotation and of course found nowhere; the step could only ever waste a
            // round trip and, if an ENSG id ever did collide, point the picture at the wrong
            // chromosome. For those species the annotation's own symbols are all there is.
            const humanKaryotype = /^(human|homo)/i.test('' + (r.species || 'human'));
            if (!hits.length && !humanKaryotype) {
                step('no synonym table for ' + (r.species || '?') + '; the annotation symbols are all there is');
            }
            if (!hits.length && humanKaryotype) {
                // Not a symbol in this annotation. It may still be a synonym, which the
                // symbol table knows and the annotation does not.
                try {
                    const alt = await GETJSON(window['env']['apiUrl'] + '/gene-lookup?key='
                        + encodeURIComponent(sym));
                    // /gene-lookup is a SUBSTRING search -- 'ALS1' returns a hundred rows,
                    // and so would half a symbol someone stopped typing. So the row is
                    // chosen rather than taken: the gene whose SYMBOL is what was typed
                    // first, then the gene carrying it as a synonym, and only then the
                    // first row. Without that, a partial symbol silently selects whichever
                    // gene happened to sort first, and points the karyotype at the wrong
                    // chromosome with no sign that it did.
                    const up = sym.toUpperCase();
                    const rows = Array.isArray(alt) ? alt : [];
                    const eq = (v) => ('' + (v == null ? '' : v)).trim().toUpperCase() === up;
                    const pick = rows.find((q) => eq(q['Gene name']))
                        || rows.find((q) => eq(q['Gene Synonym']))
                        || rows[0];
                    const id = pick && (pick['Gene stable ID'] || '');
                    const nm = pick && (pick['Gene name'] || '');
                    if (id) {
                        const how = (pick && eq(pick['Gene name'])) ? 'symbol'
                            : (pick && eq(pick['Gene Synonym'])) ? 'synonym for ' + (nm || id)
                                : 'closest match ' + (nm || id);
                        step('resolved ' + sym + ' -> ' + (nm || id) + ' (' + how + ')');
                        hits = await ask(id);
                        // Say so when the answer is not the thing that was typed.
                        if (hits.length && how !== 'symbol') {
                            hits[0].matched = how;
                        }
                    }
                } catch (e) { step('gene-lookup failed: ' + e); }
            }
            if (!hits.length) {
                // Name the genome that was searched, and say when the search could not run at
                // all -- "no gene called X" and "this server holds no annotation for that
                // species" are different answers and were both delivered as the first one.
                graph.setMessage(lastError
                    ? (' ' + lastError + ' ')
                    : (' No gene called ' + sym + ' in the ' + (r.species || 'human')
                        + ' annotation. '
                        + (humanKaryotype ? '' : 'Only the symbols in that annotation can be searched for '
                            + (r.species || 'this species') + ' — synonyms and old names are human only. ')));
                return null;
            }
            // The chromosome has to be one this karyotype is drawing -- a gene on a patch
            // contig is a real answer to the lookup and not a place on this picture.
            for (const g of hits) {
                let ci = chromIndex[('' + g.chr).replace(/^chr/, '')];
                if (ci == null) ci = chromIndex['' + g.chr];
                if (ci == null) continue;
                return { ci: ci, gene: g, lo: Math.max(0, +g.start), hi: Math.min(drawn[ci].length, +g.end) };
            }
            graph.setMessage(' ' + sym + ' is on ' + hits[0].chr
                + ', which this genome does not draw. ');
            return null;
        };

        // Find it, select it, and go there. The region is what the rest of this view
        // already understands, so a gene found by name is the same thing as a gene
        // dragged out by hand from the moment it is found.
        const gotoGene = async (raw) => {
            const f = await findGene(raw);
            if (!f) return false;
            const c = drawn[f.ci];
            regions.push({ i: f.ci, lo: f.lo, hi: f.hi });
            // A little room either side: a gene framed exactly to its own ends gives no
            // sense of where it sits.
            const pad = Math.max((f.hi - f.lo) * 0.25, 2000) / MB;
            await goView({
                x0: barLeft(f.ci) - 0.5 * SLOT, x1: barRight(f.ci) + 0.5 * SLOT,
                y0: wy(f.hi) - pad, y1: wy(f.lo) + pad
            });
            graph.setMessage(' ' + f.gene.gene + ' — ' + c.name + ':' + human(f.lo) + '-'
                + human(f.hi) + '  (' + fmtSpan(f.hi - f.lo) + ', ' + f.gene.biotype + ')'
                + (f.gene.matched === 'symbol' ? '' : ' — matched by ' + f.gene.matched)
                + ' — region ' + regions.length + '. ');
            step('gene ' + f.gene.gene + ' -> ' + c.name + ':' + f.lo + '-' + f.hi);
            return true;
        };

        // FIND A GENE IS A LIBRARY OF EVERY GENE, filled as you type. The shelf's own
        // search box asks /gene-lookup -- the same endpoint the New-track form's typeahead
        // uses -- and each hit is a card: symbol, id, description. One row per synonym
        // comes back, so hits are folded by stable id, and a pick goes by that id, which
        // findGene prefers over a name. The old modal stays below as geneMenuModal in
        // case a caller wants the typeahead form.
        const geneMenu = () => {
            const host_ = window['env']['apiUrl'];
            const hint = { note: true, title: 'Start typing a gene symbol or an old name — SOD1, TARDBP, C9orf72, ALS1 — and pick the gene from the cards.', blurb: '' };
            const search = async (text) => {
                const res = await fetch(host_ + '/gene-lookup?key=' + encodeURIComponent(text));
                if (!res.ok) throw new Error('HTTP ' + res.status);
                let rows = await res.json();
                if (!Array.isArray(rows)) rows = [];
                const seen = new Map();
                for (const r0 of rows) {
                    const id = '' + (r0['Gene stable ID'] || '');
                    const sym = '' + (r0['Gene name'] || '');
                    if (!id && !sym) continue;
                    const key = id || sym;
                    if (!seen.has(key)) seen.set(key, { id: id, sym: sym, desc: ('' + (r0['Gene description'] || '')).replace(/\s*\[Source:[^\]]*\]\s*$/, ''), syn: [], canonical: r0['Ensembl Canonical'] === '1' });
                    const s2 = '' + (r0['Gene Synonym'] || '');
                    if (s2 && seen.get(key).syn.indexOf(s2) < 0 && s2 !== sym) seen.get(key).syn.push(s2);
                }
                const hits = Array.from(seen.values());
                if (!hits.length) return [{ note: true, title: 'No gene matches "' + text + '".', blurb: '' }];
                return hits.slice(0, 60).map((h) => ({
                    title: h.sym || h.id,
                    badge: h.id || 'gene',
                    blurb: (h.desc || 'no description') + (h.syn.length ? '  ·  also ' + h.syn.slice(0, 4).join(', ') : ''),
                    open: () => gotoGene(h.id || h.sym),
                })).concat(hits.length > 60 ? [{ note: true, title: hits.length + ' genes match; the first 60 are shown. Type more to narrow it.', blurb: '' }] : []);
            };
            try {
                exec('baja/lib/shelf.js', {
                    id: 'baja-karyo-gene',
                    title: 'Find a gene',
                    subtitle: 'The gene is framed on its chromosome and added to the selected regions, so Selected regions can then open its transcripts.',
                    searchPlaceholder: 'Gene symbol, name or description…',
                    books: [hint],
                    search: search,
                    graph: graph,
                });
            } catch (e) {
                step('gene shelf threw: ' + e);
                graph.setMessage(' Find a gene could not be opened: ' + (e && e.message ? e.message : e) + ' ');
            }
        };
        const geneMenuModal = () => {
            // THE SAME TYPEAHEAD THE NEW-TRACK FORM USES. input-textfield with a
            // typeahead_url queries /gene-lookup on every keystroke and offers the rows it
            // returns, joined from the fields named here -- so a half-typed symbol, an old
            // name or a description all reach the gene, and the exact spelling is picked
            // from a list rather than remembered. 'Gene name' comes first because the
            // joined string is what lands in the box, and its first field is what a
            // symbol-only search will read back out of it; 'Gene stable ID' comes last so a
            // pick always carries an unambiguous id for findGene to prefer.
            let geneBox = null;
            const readBox = () => {
                try {
                    if (geneBox && geneBox.getWidgetValue) return geneBox.getWidgetValue();
                    if (geneBox && geneBox.value != null) return geneBox.value;
                } catch (e) { }
                return '';
            };
            showModal({
                wid: 'card',
                data: {
                    // card_padding insets the whole panel from the modal edge; padding is
                    // per cell, so the header, the field and the button are spaced down the
                    // dialog. Both, because one alone gives either text against the edge or
                    // rows with no rhythm. The blocks inside no longer pad themselves
                    // horizontally -- two paddings on one edge makes one gutter wider than
                    // the other.
                    card_padding: '20px 22px',
                    padding: '7px 0',
                    height: '400px',
                    cards: [[
                        {
                            'title': ' ', 'width': '100%',
                            'component': {
                                wid: 'html',
                                data: '<div style="padding:2px 0 10px;font:14px Arial;">'
                                    + '<b>Find a gene</b><div style="color:#5b6b7a;font:12.5px Arial;'
                                    + 'margin-top:5px;line-height:1.45;">Start typing a symbol — '
                                    + 'SOD1, TARDBP, C9orf72 — and pick it from the list. The gene '
                                    + 'is framed on its chromosome and added to the selected '
                                    + 'regions, so Regions can then open its transcripts.</div></div>'
                            }
                        },
                        {
                            'title': 'Human Gene Symbol',
                            'width': '100%',
                            'component': {
                                wid: 'input-textfield',
                                data: {
                                    'show-button': false,
                                    'title': 'Human gene symbol (e.g. SOD1, TARDBP, C9orf72)',
                                    'text': '',
                                    'typeahead_url': window['env']['apiUrl'] + '/gene-lookup',
                                    // No 'Gene Synonym' here. The endpoint carries one row
                                    // per synonym, so including it made SOD1 three visibly
                                    // different lines that all mean the same gene -- and
                                    // being different, no dedupe could collapse them.
                                    // Searching BY a synonym still works: /gene-lookup
                                    // matches the whole row, not only the fields shown.
                                    'typeahead_fields': ['Gene name', 'Gene description',
                                        'Gene stable ID'],
                                    'ionHookFunction': createIonFunction((b) => { geneBox = b; }),
                                    // Picking from the list fills the box; the button is
                                    // still the thing that acts, so a mis-click costs
                                    // nothing and does not silently add a region.
                                    'optionSelected': createIonFunction((value) => {
                                        try {
                                            const v = ('' + value).split(',')[0].trim();
                                            if (v) graph.setMessage(' ' + v + ' — press Find to select it. ');
                                        } catch (e) { }
                                    })
                                }
                            }
                        },
                        {
                            'title': ' ', 'width': '100%',
                            'component': {
                                wid: 'mt-button',
                                data: {
                                    buttons: [{
                                        label: 'Find and select',
                                        ionFunction: createIonFunction(async () => {
                                            const v = readBox();
                                            if (!('' + (v || '')).trim()) {
                                                graph.setMessage(' Type a gene symbol. ');
                                                return;
                                            }
                                            try { hideAllModal(); } catch (e) { }
                                            await gotoGene(v);
                                        })
                                    }]
                                }
                            }
                        },
                    ]]
                }
            });
        };

        // ---- WHAT YOU CAN DO WITH A SELECTED REGION -----------------------------
        //
        // A callout card used to go straight to the transcript panel, which is one of the
        // things you might want and not always the one -- and once a card is clickable at
        // all, "what else" is the obvious next question. So it opens the library instead,
        // in the same idiom the selection library uses, and the transcript panel becomes
        // one leaf of it.
        const bpCovered = (flat, lo, hi) => {
            // Merged, sorted, non-overlapping pairs from region-features.py, so a clipped
            // sum is the covered length -- no interval arithmetic beyond the clip.
            let n = 0;
            for (let q = 0; q + 1 < flat.length; q += 2) {
                const a = Math.max(lo, +flat[q]), b = Math.min(hi, +flat[q + 1]);
                if (b >= a) n += (b - a + 1);
            }
            return n;
        };
        const pct = (n, d) => (d > 0 ? (n * 100 / d).toFixed(1) + '%' : '—');

        // The statistics, as a shelf of their own. Built when it is opened rather than up
        // front: it is two server calls, and most clicks on a card are not asking for it.
        const regionStatsBooks = async (rg) => {
            const c = drawn[rg.i];
            const lo = rg.lo, hi = rg.hi, span = Math.max(1, hi - lo + 1);
            graph.setMessage(' Reading ' + c.name + ':' + human(lo) + '-' + human(hi) + '… ');

            let gc = geneCache.get(geneKey(rg));
            if (!gc || gc.state === 'pending') { await geneAsk(rg); gc = geneCache.get(geneKey(rg)); }
            const genes = (gc && gc.genes) || [];
            const coding = genes.filter((g2) => g2.coding).length;

            const F = await fetchFeatures(rg.i, 'cds,five_utr,three_utr,exon,gene', lo, hi);
            const books = [];

            // The variants this view is holding here, which the annotation knows nothing
            // about -- they are the reason the region was selected in the first place.
            const d = vdata[rg.i];
            let vN = 0, vPath = 0;
            if (d && d.n) {
                let a2 = 0, z2 = d.n;
                while (a2 < z2) { const m2 = (a2 + z2) >> 1; if (d.pos[m2] < lo) a2 = m2 + 1; else z2 = m2; }
                for (let k = a2; k < d.n && d.pos[k] <= hi; k++) {
                    vN++;
                    if (d.cls[k] === 1 || (d.hl && d.hl[k] === HL_PATHOGENIC)) vPath++;
                }
            }

            books.push({ section: 'Region', note: true, title: 'span',
                blurb: c.name + ':' + human(lo) + '-' + human(hi) + '  ·  ' + fmtSpan(span)
                    + '  ·  ' + genes.length + ' gene' + (genes.length === 1 ? '' : 's')
                    + ' (' + coding + ' protein-coding)'
                    + '  ·  ' + vN.toLocaleString() + ' variant' + (vN === 1 ? '' : 's')
                    + (vPath ? ', ' + vPath.toLocaleString() + ' pathogenic' : '') });

            if (!F) {
                books.push({ section: 'Genomic structure', note: true, title: 'unavailable',
                    blurb: 'The annotation for this region could not be read.' });
            } else {
                const gene = bpCovered(F.gene || [], lo, hi);
                const exon = bpCovered(F.exon || [], lo, hi);
                const cds = bpCovered(F.cds || [], lo, hi);
                const u5 = bpCovered(F.five_utr || [], lo, hi);
                const u3 = bpCovered(F.three_utr || [], lo, hi);
                // Intronic is gene minus exon and intergenic is the rest, because that is
                // what those words mean -- neither is a feature the file carries.
                const intron = Math.max(0, gene - exon);
                const inter = Math.max(0, span - gene);
                const row = (label, n) => ({ section: 'Genomic structure', note: true,
                    title: label, blurb: label + ': ' + n.toLocaleString() + ' bp  ('
                        + pct(n, span) + ' of the region)' });
                books.push(row('Genic', gene));
                books.push(row('Exonic', exon));
                books.push(row('Coding (CDS)', cds));
                books.push(row("5' UTR", u5));
                books.push(row("3' UTR", u3));
                books.push(row('Intronic', intron));
                books.push(row('Intergenic', inter));
            }

            if (!genes.length) {
                books.push({ section: 'Genes', note: true, title: 'none',
                    blurb: 'No genes are annotated in this region.' });
            } else {
                for (const g2 of genes) {
                    books.push({
                        section: 'Genes',
                        title: g2.gene + (g2.strand === '-' ? '  \u25c2' : '  \u25b8'),
                        badge: g2.coding ? 'coding' : (g2.biotype || ''),
                        blurb: (g2.transcript || 'no transcript in the annotation')
                            + '  ·  ' + human(g2.start) + '-' + human(g2.end)
                            + '  ·  ' + fmtSpan(Math.max(1, g2.end - g2.start + 1)),
                    });
                }
            }
            return books;
        };

        // FRAME ONE REGION: the same padding a gene found by name gets, so a lost gene
        // clicked from its callout card lands the way Find gene would land it.
        const zoomToRegion = async (rg) => {
            const ci = rg.i, lo = +rg.lo, hi = +rg.hi;
            const pad = Math.max((hi - lo) * 0.25, 2000) / MB;
            const v = { x0: barLeft(ci) - 0.5 * SLOT, x1: barRight(ci) + 0.5 * SLOT, y0: wy(hi) - pad, y1: wy(lo) + pad };
            try { flyToView(v); } catch (e) { try { await goView(v); } catch (e2) { } }
            graph.setMessage(' ' + (rg.label ? rg.label + ' — ' : '') + drawn[ci].name + ':' + human(lo) + '-' + human(hi)
                + ' (' + fmtSpan(Math.max(1, hi - lo + 1)) + ') ');
        };

        const calloutMenu = (rg) => {
            const c = drawn[rg.i];
            const where = c.name + ':' + human(rg.lo) + '-' + human(rg.hi);
            const n = regions.indexOf(rg);
            try {
                exec('baja/lib/shelf.js', {
                    id: 'baja-region-actions',
                    title: rg.label ? ('' + rg.label) : where,
                    subtitle: (rg.label ? where + '  ·  ' : '') + fmtSpan(Math.max(1, rg.hi - rg.lo + 1))
                        + (n >= 0 ? '  ·  region ' + (n + 1) + ' of ' + regions.length : ''),
                    books: (rg.lof && rg.gene ? [{
                        title: isSelected(rg.gene) ? 'Deselect ' + rg.gene : 'Select ' + rg.gene + ' for analysis',
                        badge: isSelected(rg.gene) ? 'selected' : selWord() + ' selected', icon: 'checklist',
                        blurb: isSelected(rg.gene) ? 'Take it out of the set the microscope works on.'
                            : 'Add it to the set the microscope works on: synthetic-lethal targets, paralog partners. A single click on the label does the same.',
                        open: () => { const on = toggleGeneSelect(lofRecordFor(rg)); graph.setMessage(' ' + rg.gene + (on ? ' selected' : ' deselected') + ' — ' + selWord() + '. '); if (graph.wake) graph.wake(); calloutMenu(rg); },
                    }] : []).concat([
                        {
                            title: 'Zoom into',
                            badge: rg.lof ? 'lost gene' : 'view',
                            blurb: 'Fly the camera to ' + where + ' and frame it with a little room either side'
                                + (rg.lof ? ', so the loss-of-function variant can be clicked' : '') + '.',
                            open: () => zoomToRegion(rg),
                        },
                        {
                            title: 'Open in oligo editor',
                            badge: 'transcripts',
                            blurb: 'List the transcripts here, tick the ones you want, and load '
                                + 'them into the editor with the variants that fall inside them.',
                            open: () => openRegions([rg]),
                        },
                        {
                            title: 'Sequence statistics',
                            badge: 'annotation',
                            blurb: 'What is in this region: its genes, and how much of it is '
                                + 'coding, UTR, intronic and intergenic.',
                            books: () => regionStatsBooks(rg),
                        },
                        {
                            title: 'Deselect',
                            badge: 'region',
                            blurb: 'Drop this region from the selection. The variants in it are '
                                + 'left exactly as they are.',
                            open: () => {
                                const at = regions.indexOf(rg);
                                if (at >= 0) regions.splice(at, 1);
                                if (activeRegion === geneKey(rg)) activeRegion = null;
                                if (graph.wake) graph.wake();
                                graph.setMessage(' ' + where + ' deselected — '
                                    + regions.length + ' region'
                                    + (regions.length === 1 ? '' : 's') + ' left. ');
                            },
                        },
                    ]),
                    graph: graph,
                });
            } catch (e) {
                step('region menu threw: ' + e);
                graph.setMessage(' That region menu could not be opened: '
                    + (e && e.message ? e.message : e) + ' ');
            }
        };

        // The camera. One button opens this; everything about bookmarks happens in it.
        // `deleting` swaps what a click on a bookmark does -- go there, or drop it --
        // rather than putting a second control beside every row, which for sixty rows is
        // a hundred and twenty things to read instead of sixty.
        // BOOKMARKS ARE A LIBRARY OF VIEWS. The same shelf as the rest of the toolbar:
        // one card to keep the view showing now, then a card per view kept, and Remove
        // as a sub-library so taking one away is a choice made among the same cards.
        // The name of a new bookmark is typed in the shelf's own box: the box is wired
        // as a search, so what is typed does not filter the cards away -- it relabels
        // the keep card, which saves under that name. Untyped, the view names itself.
        // ---- DOWNLOAD LIBRARY --------------------------------------------------------------
        // The same idiom as the editor's Download (baja/lib/shelf.js): whole genome -> a
        // chromosome -> the selected regions, each ending in a format. Variants are the payload;
        // BED/JSON/CSV are built here, XLSX/PDF by /export-table. Huge variant sets are capped so
        // a browser is never asked to build millions of rows.
        const DL_ROW_CAP = 200000;       // in-browser BED/JSON/CSV
        const DL_SERVER_CAP = 50000;     // XLSX/PDF via /export-table
        const dlHost = window['env']['apiUrl'];
        const dlSafe = (x) => ('' + (x == null ? '' : x)).replace(/[^A-Za-z0-9_\- .]+/g, '_').replace(/\s+/g, '_').replace(/_+/g, '_').replace(/^_|_$/g, '') || 'karyotype';
        const dlMsg = (m) => { try { if (graph && graph.setMessage) graph.setMessage(' ' + m + ' '); } catch (e) { } };
        const dlErr = (m) => { try { if (graph && graph.setError) graph.setError(m, 8); else dlMsg(m); } catch (e) { } };
        const dlSaveText = (text, filename, mime) => {
            try {
                const a = document.createElement('a');
                a.href = URL.createObjectURL(new Blob([text], { type: (mime || 'text/plain') + ';charset=utf-8;' }));
                a.download = filename; a.style.display = 'none';
                document.body.appendChild(a); a.click();
                setTimeout(() => { try { document.body.removeChild(a); URL.revokeObjectURL(a.href); } catch (e) { } }, 500);
            } catch (e) { dlErr('Could not start the download: ' + e); }
        };
        // A file made of many pieces. Blob takes the list and concatenates OUTSIDE the
        // JavaScript heap, so nothing here ever holds the whole document at once.
        const dlSaveParts = (parts, filename, mime) => {
            try {
                const a = document.createElement('a');
                a.href = URL.createObjectURL(new Blob(parts, { type: (mime || 'text/plain') + ';charset=utf-8;' }));
                try { parts.length = 0; } catch (e) { }
                a.download = filename; a.style.display = 'none';
                document.body.appendChild(a); a.click();
                setTimeout(() => { try { document.body.removeChild(a); URL.revokeObjectURL(a.href); } catch (e) { } }, 500);
            } catch (e) { dlErr('Could not start the download: ' + e); }
        };
        const dlSaveB64 = (b64, filename, mime) => {
            try {
                const bin = atob(b64); const bytes = new Uint8Array(bin.length);
                for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
                const a = document.createElement('a');
                a.href = URL.createObjectURL(new Blob([bytes], { type: mime || 'application/octet-stream' }));
                a.download = filename; a.style.display = 'none';
                document.body.appendChild(a); a.click();
                setTimeout(() => { try { document.body.removeChild(a); URL.revokeObjectURL(a.href); } catch (e) { } }, 500);
            } catch (e) { dlErr('Could not save the file: ' + e); }
        };
        const dlCell = (v) => { let x = (v == null) ? '' : ('' + v); if (/[",\n\r]/.test(x)) x = '"' + x.replace(/"/g, '""') + '"'; return x; };
        const dlColumns = (rows) => { const seen = []; for (const r of rows) for (const k in r) if (seen.indexOf(k) < 0) seen.push(k); return seen; };
        const dlToCSV = (rows) => { const c = dlColumns(rows); return c.map(dlCell).join(',') + '\n' + rows.map((r) => c.map((k) => dlCell(r[k])).join(',')).join('\n'); };
        const dlToBED = (rows) => rows.filter((b) => b && b.chrom && b.start !== '' && b.end !== '')
            .map((b) => [b.chrom, b.start, b.end, ('' + (b.name == null || b.name === '' ? '.' : b.name)).replace(/\s+/g, '_'), '.', '.'].join('\t')).join('\n') + '\n';

        const dlVariantRow = (ci, k) => {
            const d = vdata[ci]; const ab = allelesAt(ci, k);
            return { chrom: drawn[ci].name, pos: d.pos[k], ref: ab[0], alt: ab[1],
                significance: (function () { try { return sigOf(d, k) || ''; } catch (e) { return CLS_SIG[d.cls[k]] || ''; } })(),
                name: (d.names && d.names[k]) || '',
                ...(function () {
                    try {
                        const i = cvRowAt(ci, k);
                        if (i < 0) return { clinvar_variation_id: '', review_stars: '', gene: '', condition: '' };
                        const R = cvRecord(ci, i);
                        return { clinvar_variation_id: R.vid, review_stars: R.stars, gene: R.gene, condition: R.cond };
                    } catch (e) { return { clinvar_variation_id: '', review_stars: '', gene: '', condition: '' }; }
                })() };
        };
        const dlVariantBed = (ci, k) => {
            const d = vdata[ci];
            return { chrom: drawn[ci].name, start: Math.max(0, (d.pos[k] | 0) - 1), end: (d.pos[k] | 0),
                name: (d.names && d.names[k]) || (drawn[ci].name + ':' + d.pos[k]) };
        };
        // Collect up to `cap` variant indices for a set of chromosomes, optionally clipped to
        // regions. Returns { pairs:[[ci,k]...], total, truncated }.
        const dlCollect = (chromList, regionList, cap) => {
            const pairs = []; let total = 0, truncated = false;
            const inReg = (ci, pos) => { if (!regionList) return true; for (const r of regionList) { if (r.i === ci && pos >= r.lo && pos <= r.hi) return true; } return false; };
            for (const ci of chromList) {
                const d = vdata[ci]; if (!d || !d.n || !d.pos) continue;
                for (let k = 0; k < d.n; k++) {
                    if (regionList && !inReg(ci, d.pos[k])) continue;
                    total++;
                    if (pairs.length < cap) pairs.push([ci, k]); else truncated = true;
                }
            }
            return { pairs: pairs, total: total, truncated: truncated };
        };
        const dlCountVariants = (chromList, regionList) => {
            let total = 0;
            const inReg = (ci, pos) => { if (!regionList) return true; for (const r of regionList) { if (r.i === ci && pos >= r.lo && pos <= r.hi) return true; } return false; };
            for (const ci of chromList) { const d = vdata[ci]; if (!d || !d.n || !d.pos) continue; if (!regionList) { total += d.n; continue; } for (let k = 0; k < d.n; k++) if (inReg(ci, d.pos[k])) total++; }
            return total;
        };
        const dlAllChroms = () => drawn.map((c, i) => i);
        const dlSpecies = () => { try { return (r && r.species) || wanted || 'genome'; } catch (e) { return 'genome'; } };
        const dlAssembly = () => { try { return ('' + ((r && r.assembly) || '')); } catch (e) { return ''; } };

        const dlRunFormat = async (scope, fmt) => {
            try {
                const cap = (fmt === 'xlsx' || fmt === 'pdf') ? DL_SERVER_CAP : DL_ROW_CAP;
                const col = dlCollect(scope.chroms, scope.regions || null, cap);
                if (!col.pairs.length) { dlMsg('Nothing to download in that selection.'); return; }
                if (col.truncated) dlMsg('Large set — downloading the first ' + cap.toLocaleString() + ' of ' + col.total.toLocaleString() + ' variants.');
                if (fmt === 'json') { dlSaveText(JSON.stringify(col.pairs.map((p) => dlVariantRow(p[0], p[1])), null, 2), scope.base + '.json', 'application/json'); return; }
                if (fmt === 'csv') { dlSaveText(dlToCSV(col.pairs.map((p) => dlVariantRow(p[0], p[1]))), scope.base + '.csv', 'text/csv'); return; }
                if (fmt === 'bed') { dlSaveText(dlToBED(col.pairs.map((p) => dlVariantBed(p[0], p[1]))), scope.base + '.bed', 'text/plain'); return; }
                if (fmt === 'xlsx' || fmt === 'pdf') {
                    dlMsg('Building the ' + fmt.toUpperCase() + '…');
                    const rows = col.pairs.map((p) => dlVariantRow(p[0], p[1]));
                    const r = await POSTJSON({ format: fmt, filename: scope.base, title: scope.title, sheets: [{ name: 'Variants', rows: rows }] }, dlHost + '/export-table');
                    const body = (r && r.error && typeof r.error === 'object') ? r.error : r;
                    if (body && body.b64) { dlSaveB64(body.b64, body.filename || (scope.base + '.' + fmt), body.mime); dlMsg((body.filename || scope.base) + ' downloaded.'); }
                    else { dlErr('Could not build the ' + fmt.toUpperCase() + ': ' + ((body && (body.error || body.message)) || 'server error')); }
                }
            } catch (e) { dlErr('Download failed: ' + e); }
        };
        const dlFormatBooks = (scope) => {
            const n = dlCountVariants(scope.chroms, scope.regions || null);
            const heavy = n > DL_SERVER_CAP;
            const books = [
                { title: 'BED', badge: '.bed', leaf: true, ready: true, blurb: 'Genomic positions, tab-separated.', open: () => dlRunFormat(scope, 'bed') },
                { title: 'JSON', badge: '.json', leaf: true, ready: true, blurb: 'The variant records.', open: () => dlRunFormat(scope, 'json') },
                { title: 'CSV', badge: '.csv', leaf: true, ready: true, blurb: 'One row per variant.', open: () => dlRunFormat(scope, 'csv') },
                { title: 'Excel (XLSX)', badge: '.xlsx', leaf: true, ready: !heavy, readyNote: 'Too many variants for a spreadsheet — narrow to a chromosome or region.', blurb: 'A spreadsheet of the variants.', open: () => dlRunFormat(scope, 'xlsx') },
                { title: 'PDF', badge: '.pdf', leaf: true, ready: !heavy, readyNote: 'Too many variants for a PDF — narrow to a chromosome or region.', blurb: 'A printable listing.', open: () => dlRunFormat(scope, 'pdf') }
            ];
            return books;
        };
        const downloadMenu = () => {
            try { if (typeof hideAllModal === 'function') hideAllModal(); } catch (e) { }
            const base = dlSafe(dlSpecies() + (dlAssembly() ? ('_' + dlAssembly()) : ''));
            const genomeScope = { chroms: dlAllChroms(), base: base + '_variants', title: dlSpecies() + ' — all variants' };
            const books = [];
            const totalN = vtotal || dlCountVariants(dlAllChroms(), null);
            books.push({ section: 'Download genome', note: true, title: 'Every variant on the genome (' + (totalN ? totalN.toLocaleString() : '0') + ') — pick a format:' });
            dlFormatBooks(genomeScope).forEach((b) => books.push(Object.assign({}, b, { section: 'Download genome' })));
            if (Array.isArray(regions) && regions.length) {
                const rScope = { chroms: Array.from(new Set(regions.map((r) => r.i))), regions: regions.slice(), base: base + '_regions', title: dlSpecies() + ' — selected regions' };
                books.push({ section: 'Selected regions', note: true, title: 'The variants inside the ' + regions.length + ' selected region' + (regions.length === 1 ? '' : 's') + ':' });
                dlFormatBooks(rScope).forEach((b) => books.push(Object.assign({}, b, { section: 'Selected regions' })));
            }
            const withV = drawn.map((c, i) => i).filter((i) => vdata[i] && vdata[i].n);
            if (withV.length) {
                books.push({ section: 'By chromosome', note: true, title: 'Download one chromosome:' });
                withV.forEach((i) => books.push({
                    section: 'By chromosome', title: drawn[i].name, badge: (vdata[i].n.toLocaleString()), ready: true,
                    blurb: vdata[i].n.toLocaleString() + ' variant' + (vdata[i].n === 1 ? '' : 's'),
                    books: () => dlFormatBooks({ chroms: [i], base: base + '_' + dlSafe(drawn[i].name), title: dlSpecies() + ' — ' + drawn[i].name })
                }));
            }
            exec('baja/lib/shelf.js', {
                id: 'baja-karyo-download',
                title: 'Download',
                subtitle: 'Download the genome variants — whole genome, a chromosome, or the selected regions',
                graph: graph,
                books: books
            });
        };

        // ---- SHARE -------------------------------------------------------------------------
        // Mirrors the editor's Share: a public view-only link (anyone, no login, opened by the
        // exempt manchester/viewer.js) and a per-person share (an email invite; opened in this
        // viewer after sign-in). Both carry a stateDoc() snapshot, so the shared karyotype has
        // its variants, view and bookmarks.
        const shareBaseName = () => {
            let fn = '';
            try { const st = window.history.state; fn = (st && st.karyotype) ? ('' + st.karyotype).split('/').pop().replace(GENOME_FILE_RE, '') : ''; } catch (e) { }
            return dlSafe(fn || (dlSpecies() + (dlAssembly() ? ('_' + dlAssembly()) : '')) || 'genome');
        };
        const shareEsc = (v) => ('' + (v == null ? '' : v)).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
        const shareKaryoPublic = async () => {
            const host_ = window['env']['apiUrl']; const user = ('' + (getUser() || '')).trim();
            if (!user) { dlErr('Sign in to share.'); return; }
            dlMsg('Creating a public view-only link…');
            try {
                // THE SAME PIECES THE SAVE USES. A shared whole genome is the same size as
                // a saved one, and building it as a single string was the allocation that
                // took the tab down. Over the direct limit it goes up in chunks instead.
                const __b = stateParts();
                const name = shareBaseName() + SAVE_EXT;
                __b.parts[0] = __b.parts[0] + ',"name":' + JSON.stringify(name);
                const blob = new Blob(__b.parts, { type: 'application/json' });
                __b.parts.length = 0;
                let saveRs = null;
                if (blob.size > SAVE_DIRECT_MAX) {
                    const up = await uploadToMyFiles(new File([blob], name, { type: 'application/json' }),
                        () => { }, 'public');
                    if (up && up.error) throw new Error(up.error);
                    saveRs = { status: 'saved', path: '/' + user + '/public/' + name };
                } else {
                    saveRs = await POSTJSON({ name: name, key: 'user', user: user, spath: 'public', value: await blob.text() }, host_ + '/save-user-data');
                }
                try { await POSTJSON({ name: '.share', key: 'user', user: user, spath: 'public', value: 'public\n/public' }, host_ + '/save-user-data'); } catch (e) { }
                const sharedPath = (saveRs && saveRs.path) ? saveRs.path : ('/' + user + '/public/' + name);
                let link = window.location.origin + '/app/manchester/viewer?path=' + encodeURIComponent(sharedPath);
                try { const al = await POSTJSON({ path: sharedPath }, host_ + '/share-alias'); if (al && al.code) link = window.location.origin + '/s/' + al.code; } catch (e) { }
                try { if (navigator.clipboard && navigator.clipboard.writeText) await navigator.clipboard.writeText(link); } catch (e) { }
                showModal({ wid: 'html', data: '<div style="padding:18px 20px;font-family:system-ui,-apple-system,Arial;max-width:520px;">'
                    + '<div style="font-size:15px;font-weight:700;margin-bottom:8px;">Public link created</div>'
                    + '<div style="font-size:12px;color:#475569;margin-bottom:10px;">Copied to your clipboard. Anyone with this link can view this genome — no login required.</div>'
                    + '<div style="font-size:12px;word-break:break-all;background:#f1f5f9;border:1px solid #e2e8f0;border-radius:6px;padding:8px 10px;"><a href="' + shareEsc(link) + '" target="_blank" style="color:#1d4ed8;">' + shareEsc(link) + '</a></div></div>' }, 560, 220);
                dlMsg('Public link copied to clipboard.');
            } catch (e) { dlErr('Could not create the link: ' + e); }
        };
        const shareKaryoWithPerson = () => {
            const host_ = window['env']['apiUrl']; const user = ('' + (getUser() || '')).trim();
            if (!user) { dlErr('Sign in to share.'); return; }
            const designName = shareBaseName() + SAVE_EXT;
            const body = (r) => (r && r.error && typeof r.error === 'object') ? r.error : r;
            try { const old = document.getElementById('baja-karyo-share-dialog'); if (old && old.parentNode) old.parentNode.removeChild(old); } catch (e) { }
            const backdrop = document.createElement('div');
            backdrop.style.cssText = 'position:fixed;inset:0;z-index:2147482999;background:rgba(0,0,0,0.35);';
            const panel = document.createElement('div');
            panel.id = 'baja-karyo-share-dialog';
            panel.style.cssText = 'position:fixed;top:60px;left:50%;transform:translateX(-50%);z-index:2147483000;width:min(560px,94vw);max-height:calc(100vh - 90px);overflow:auto;background:#0b2545;color:#fff;border-radius:12px;box-shadow:0 12px 40px rgba(0,0,0,0.45);border:1px solid rgba(255,255,255,0.14);font-family:Arial,Helvetica,sans-serif;padding:18px;';
            const fc = 'width:100%;box-sizing:border-box;background:#0a1e3a;color:#e8f0fb;border:1px solid rgba(255,255,255,0.16);border-radius:8px;padding:10px;font:13px Arial;';
            panel.innerHTML = ''
                + '<button id="ks-x" title="Close" aria-label="Close" style="position:absolute;top:8px;right:10px;cursor:pointer;border:none;background:transparent;color:#9fb3c8;font:700 18px Arial;line-height:1;padding:4px 8px;">✕</button>'
                + '<div style="font:700 16px Arial;margin-bottom:4px;padding-right:24px;">Share this genome with a person</div>'
                + '<div style="font:13px Arial;color:#9fb3c8;margin-bottom:12px;">They get a short link that opens this genome once they sign in. No account yet? The link takes them through the free sign-in first.</div>'
                + '<label style="font:12px Arial;color:#9fb3c8;">Email address (one or more, comma-separated)</label>'
                + '<input id="ks-to" type="text" autocomplete="off" placeholder="name@example.org" style="' + fc + 'margin:4px 0 10px;">'
                + '<label style="font:12px Arial;color:#9fb3c8;">Message (optional)</label>'
                + '<textarea id="ks-msg" rows="2" placeholder="A note to go with the genome" style="' + fc + 'margin:4px 0 10px;resize:vertical;"></textarea>'
                + '<div id="ks-status" style="font:12px Arial;color:#9fb3c8;min-height:16px;margin-bottom:6px;"></div>'
                + '<div id="ks-results"></div>'
                + '<div style="display:flex;gap:10px;justify-content:flex-end;margin-top:10px;">'
                + '<button id="ks-close" style="cursor:pointer;border-radius:8px;padding:9px 16px;font:700 13px Arial;border:1px solid rgba(255,255,255,0.22);background:transparent;color:#fff;">Close</button>'
                + '<button id="ks-send" style="cursor:pointer;border-radius:8px;padding:9px 18px;font:700 13px Arial;border:1px solid #22c55e;background:#22c55e;color:#04210f;">Share</button></div>';
            document.body.appendChild(backdrop); document.body.appendChild(panel);
            const $ = (id) => panel.querySelector('#' + id);
            let onKey;
            const close = () => { try { if (panel.parentNode) panel.parentNode.removeChild(panel); } catch (e) { } try { if (backdrop.parentNode) backdrop.parentNode.removeChild(backdrop); } catch (e) { } try { if (onKey) document.removeEventListener('keydown', onKey, true); } catch (e) { } };
            $('ks-close').onclick = close; $('ks-x').onclick = close; backdrop.onclick = close;
            onKey = (e) => { if (e.key === 'Escape') { e.preventDefault(); close(); } };
            document.addEventListener('keydown', onKey, true);
            $('ks-send').onclick = async () => {
                const raw = ('' + ($('ks-to').value || '')).split(/[\s,;]+/).map((x) => x.trim().toLowerCase()).filter(Boolean);
                const addrs = Array.from(new Set(raw));
                const bad = addrs.filter((a) => !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(a));
                if (!addrs.length) { $('ks-status').textContent = 'Enter at least one email address.'; return; }
                if (bad.length) { $('ks-status').textContent = 'Not an email address: ' + bad.join(', '); return; }
                const message = ('' + ($('ks-msg').value || '')).trim();
                const btn = $('ks-send'); btn.disabled = true; btn.textContent = 'Sharing…';
                // BUILT IN PIECES, AND MEASURED BEFORE IT IS MADE CONTIGUOUS.
                //
                // /share-with takes the document as a value in the request body, once per
                // recipient, so a whole genome cannot go this way at all -- and finding that
                // out by allocating a three-hundred-megabyte string first is how the tab
                // died. The size is known from the Blob, which never enters the heap; over
                // the limit this says so and points at the public link, which does have a
                // chunked road.
                let value = '';
                try {
                    const __sb = stateParts();
                    const __blob = new Blob(__sb.parts, { type: 'application/json' });
                    __sb.parts.length = 0;
                    if (__blob.size > SAVE_DIRECT_MAX) {
                        $('ks-status').textContent = 'This genome is ' + fmtBytes(__blob.size)
                            + ' \u2014 too large to send a copy to each person. Use \u201cShare a public link\u201d instead, '
                            + 'which uploads it once, or save it and share the file.';
                        btn.disabled = false; btn.textContent = 'Share';
                        return;
                    }
                    value = await __blob.text();
                } catch (e) { $('ks-status').textContent = 'Could not serialize: ' + e; btn.disabled = false; btn.textContent = 'Share'; return; }
                $('ks-status').textContent = 'Saving a copy for ' + (addrs.length === 1 ? addrs[0] : addrs.length + ' people') + '…';
                let firstLink = '';
                for (const to of addrs) {
                    const r = body(await POSTJSON({ user: user, to: to, name: designName, value: value, message: message }, host_ + '/share-with'));
                    if (r && r.url) {
                        if (!firstLink) firstLink = r.url;
                        const mail = r.mailed ? ('<span style="color:#86efac;">Emailed to ' + shareEsc(to) + '.</span>') : ('<span style="color:#fcd34d;">Email not sent' + (r.mailError ? ' (' + shareEsc(r.mailError) + ')' : '') + ' — copy the link and send it.</span>');
                        $('ks-results').insertAdjacentHTML('beforeend', '<div style="background:#0a1e3a;border:1px solid rgba(255,255,255,0.12);border-radius:8px;padding:8px 10px;margin:6px 0;font:12px Arial;"><b>' + shareEsc(to) + '</b><div style="word-break:break-all;margin-top:4px;"><a href="' + shareEsc(r.url) + '" target="_blank" style="color:#4fd0e6;">' + shareEsc(r.url) + '</a></div><div style="margin-top:4px;">' + mail + '</div></div>');
                    } else {
                        $('ks-results').insertAdjacentHTML('beforeend', '<div style="font:12px Arial;color:#fca5a5;margin:6px 0;">' + shareEsc(to) + ': ' + shareEsc((r && (r.error || r.message)) || 'sharing failed') + '</div>');
                    }
                }
                if (firstLink && addrs.length === 1) { try { await navigator.clipboard.writeText(firstLink); } catch (e) { } }
                $('ks-status').textContent = firstLink ? ('Shared.' + (addrs.length === 1 ? ' Link on your clipboard.' : '')) : 'Nothing was shared.';
                $('ks-to').value = ''; btn.disabled = false; btn.textContent = 'Share';
            };
            try { $('ks-to').focus(); } catch (e) { }
        };
        const shareMenu = () => {
            try { if (typeof hideAllModal === 'function') hideAllModal(); } catch (e) { }
            const user = ('' + (getUser() || '')).trim();
            if (!user) { dlErr('Sign in to share a genome.'); return; }
            exec('baja/lib/shelf.js', {
                id: 'baja-karyo-share',
                title: 'Share',
                subtitle: 'Share this genome with named people, or as a public view-only link',
                graph: graph,
                books: [
                    { title: 'Share with people', badge: 'By email', ready: true, leaf: true, blurb: 'Name one or more email addresses; each gets a private link that opens this genome once they sign in — free if they have no account.', open: () => { try { shareKaryoWithPerson(); } catch (e) { dlErr('Could not open sharing: ' + e); } } },
                    { title: 'Public view-only link', badge: 'Anyone', ready: true, blurb: 'A link anyone can open, no login, read-only.', books: () => [
                        { note: true, title: 'A public link needs no login: anyone who has it can VIEW this genome, including the variants on it. Do not create a public link for identifiable or sensitive genetic data.' },
                        { title: 'Create the public link', badge: 'Confirm', ready: true, leaf: true, blurb: 'Publish this genome as a read-only public link and copy it to your clipboard.', open: () => { shareKaryoPublic(); } }
                    ] }
                ]
            });
        };

        // A lower-left bookmark navigator, the karyotype's version of the editor's
        // bookmark-nav: it lists the saved views and flies to one on click (goView), with a
        // green Download button at the bottom. Toggles: a second call takes it down. Auto-opens
        // for a shared karyotype that carries bookmarks.
        // LEAVE WITH THE KARYOTYPE. A panel fixed to the viewport and hung off <body>
        // outlives this screen: open the editor or the home menu and it stays in the
        // corner, describing a genome that is no longer there. This watches the graph's
        // own canvas -- the one element that IS the screen -- and takes the panel down when
        // that canvas leaves the document, or has been hidden for two consecutive checks (a
        // single check would also catch a modal that briefly hides the canvas and puts it
        // back). Returns the close function, so a panel's own ✕ stops the watcher too.
        // Same watch as the editor's bookmark-nav.js.
        const leaveWithKaryotype = (panel) => {
            const hostEl = () => {
                try {
                    const c = graph && graph.canvas;
                    if (!c) return null;
                    if (c.canvas && c.canvas.nativeElement) return c.canvas.nativeElement;
                    if (c.nativeElement) return c.nativeElement;
                    if (typeof HTMLElement !== 'undefined' && c instanceof HTMLElement) return c;
                } catch (e) { }
                return null;
            };
            const shown = (el) => {
                try { return !!(el && el.isConnected && (el.offsetWidth || el.offsetHeight || el.getClientRects().length)); }
                catch (e) { return true; }
            };
            let watchTimer = 0, observer = null, hiddenTicks = 0;
            const stopWatch = () => {
                if (watchTimer) { clearInterval(watchTimer); watchTimer = 0; }
                try { if (observer) observer.disconnect(); } catch (e) { }
                observer = null;
                try { window.removeEventListener('popstate', check); window.removeEventListener('hashchange', check); } catch (e) { }
            };
            const close = () => { stopWatch(); try { if (panel.parentNode) panel.parentNode.removeChild(panel); } catch (e) { } };
            const check = () => {
                if (!panel.isConnected) { stopWatch(); return; }
                const h = hostEl();
                if (!h) return;                          // no canvas to judge by: leave it to ✕
                if (!h.isConnected) { close(); return; }  // the genome is gone
                if (shown(h)) { hiddenTicks = 0; return; }
                if (++hiddenTicks >= 2) close();
            };
            try {
                watchTimer = setInterval(check, 800);
                observer = new MutationObserver(() => { try { check(); } catch (e) { } });
                observer.observe(document.body, { childList: true, subtree: true });
                window.addEventListener('popstate', check);
                window.addEventListener('hashchange', check);
            } catch (e) { }
            return close;
        };

        const bookmarkNav = () => {
            const id = 'baja-karyo-booknav';
            try { const ex = document.getElementById(id); if (ex && ex.parentNode) { ex.parentNode.removeChild(ex); return; } } catch (e) { }
            const esc = (x) => ('' + (x == null ? '' : x)).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
            const panel = document.createElement('div');
            panel.id = id;
            // On the public IP viewer the free-tier subscribe banner sits along the bottom, so
            // the panel is lifted clear of it (and its Download footer is dropped below).
            const __navBottom = __ipPublic ? '84px' : '14px';
            panel.style.cssText = 'position:fixed;left:14px;bottom:' + __navBottom + ';z-index:2147482000;width:230px;max-height:52vh;display:flex;flex-direction:column;background:#0b2545;color:#e8f0fb;border:1px solid rgba(255,255,255,0.16);border-radius:12px;box-shadow:0 10px 34px rgba(0,0,0,0.45);font-family:Arial,Helvetica,sans-serif;overflow:hidden;';
            const header = document.createElement('div');
            header.style.cssText = 'flex:0 0 auto;display:flex;align-items:center;gap:8px;padding:10px 12px;background:#0a1e3a;border-bottom:1px solid rgba(255,255,255,0.12);';
            header.innerHTML = '<span style="font-size:16px;line-height:1;">📷</span><span style="font:700 13px Arial;flex:1;">Bookmarks</span><button id="kn-min" title="Collapse" style="cursor:pointer;border:none;background:transparent;color:#9fb3c8;font:700 15px Arial;line-height:1;padding:2px 6px;">–</button><button id="kn-x" title="Hide" style="cursor:pointer;border:none;background:transparent;color:#9fb3c8;font:700 14px Arial;line-height:1;padding:2px 6px;">✕</button>';
            const list = document.createElement('div');
            list.style.cssText = 'flex:1 1 auto;overflow:auto;padding:8px;display:flex;flex-direction:column;gap:6px;';
            if (!bookmarks.length) {
                const hint = document.createElement('div');
                hint.style.cssText = 'font:12px Arial;color:#9fb3c8;padding:6px 4px;line-height:1.5;';
                hint.innerHTML = 'No bookmarks yet.<br>Keep a view from the <b>Bookmarks</b> button.';
                list.appendChild(hint);
            } else {
                bookmarks.forEach((bk, i) => {
                    const b = document.createElement('button');
                    b.style.cssText = 'text-align:left;cursor:pointer;border:1px solid rgba(255,255,255,0.12);background:#0a1e3a;color:#e8f0fb;border-radius:8px;padding:8px 10px;font:13px Arial;';
                    b.innerHTML = '<div style="font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + esc(bk.name || ('view ' + (i + 1))) + '</div>';
                    b.onmouseenter = () => { b.style.background = '#123a63'; };
                    b.onmouseleave = () => { b.style.background = '#0a1e3a'; };
                    b.onclick = () => { try { flyToView(bk); } catch (e) { try { goView(bk); } catch (e2) { } } };
                    list.appendChild(b);
                });
            }
            // The Download footer is for the full viewer only; the public IP viewer has no
            // download and shows just the list.
            let footer = null;
            if (!__ipPublic) {
                footer = document.createElement('div');
                footer.style.cssText = 'flex:0 0 auto;padding:8px;border-top:1px solid rgba(255,255,255,0.12);';
                const dl = document.createElement('button');
                dl.title = 'Download';
                dl.style.cssText = 'width:100%;box-sizing:border-box;cursor:pointer;border:none;border-radius:8px;padding:9px 12px;font:700 13px Arial;background:#16a34a;color:#eafff2;display:flex;align-items:center;justify-content:center;gap:8px;';
                dl.innerHTML = '<span class="material-icons" style="font-size:18px;line-height:1;">file_download</span><span>Download</span>';
                dl.onclick = () => { try { downloadMenu(); } catch (e) { } };
                footer.appendChild(dl);
            }
            let collapsed = false; try { collapsed = sessionStorage.getItem('baja.karyoBookNav.collapsed') === '1'; } catch (e) { }
            const apply = () => { list.hidden = collapsed; if (footer) footer.hidden = collapsed; try { header.querySelector('#kn-min').textContent = collapsed ? '+' : '–'; } catch (e) { } try { sessionStorage.setItem('baja.karyoBookNav.collapsed', collapsed ? '1' : '0'); } catch (e) { } };
            panel.appendChild(header); panel.appendChild(list); if (footer) panel.appendChild(footer);
            document.body.appendChild(panel); apply();
            const close = leaveWithKaryotype(panel);
            header.querySelector('#kn-min').onclick = () => { collapsed = !collapsed; apply(); };
            header.querySelector('#kn-x').onclick = () => close();
        };

        const bookmarkMenu = () => {
            const here = viewOf();
            const suggested = describeView(here);
            const when = (b) => { try { return b.at ? new Date(b.at).toLocaleString() : ''; } catch (e) { return ''; } };
            const keepCard = (name) => ({
                section: 'Keep this view',
                title: name ? 'Bookmark this view as \u201c' + name + '\u201d' : 'Bookmark this view',
                badge: 'showing now',
                blurb: suggested + (name ? '' : '  \u00b7  type a name in the box above to call it something else') + '. It is written into the file when you Save.',
                open: () => {
                    const v = viewOf();
                    if (!v) { graph.setMessage(' There is no view to bookmark yet. '); return; }
                    if (bookmarks.length >= BOOKMARK_CAP) {
                        graph.setMessage(' That is ' + BOOKMARK_CAP + ' bookmarks \u2014 remove one before adding another. ');
                        return;
                    }
                    const nm = ('' + (name || '')).trim().replace(/[\r\n]+/g, ' ').slice(0, 80) || describeView(v);
                    bookmarks.push({ name: nm, x0: v.x0, x1: v.x1, y0: v.y0, y1: v.y1, at: new Date().toISOString() });
                    graph.setMessage(' Bookmarked \u201c' + nm + '\u201d. Save the file to keep it. ');
                },
            });
            const viewCards = () => bookmarks.map((bk, k) => ({
                section: 'Saved views (' + bookmarks.length + ')',
                title: bk.name || ('view ' + (k + 1)),
                badge: 'view ' + (k + 1),
                blurb: describeView(bk) + (when(bk) ? '  \u00b7  ' + when(bk) : ''),
                open: async () => {
                    try { flyToView(bk); } catch (e) { try { await goView(bk); } catch (e2) { } }
                    graph.setMessage(' ' + (bk.name || 'Bookmark') + '. ');
                },
            }));
            const removeCards = () => bookmarks.map((bk, k) => ({
                title: 'Remove \u201c' + (bk.name || ('view ' + (k + 1))) + '\u201d',
                badge: 'remove',
                blurb: describeView(bk) + '. Gone from this genome; save the file to keep the change.',
                open: () => {
                    const at = bookmarks.indexOf(bk);
                    const gone = at >= 0 ? bookmarks.splice(at, 1)[0] : null;
                    graph.setMessage(' Removed ' + (gone && gone.name ? gone.name : 'that bookmark') + '. Save the file to keep the change. ');
                },
            }));
            const panelCard = { section: 'Bookmark panel', title: 'Show / hide the bookmark panel', badge: 'panel', blurb: 'A small navigator in the lower-left corner with a Download button.', open: () => { bookmarkNav(); } };
            const booksFor = (name) => [panelCard, keepCard(name)].concat(viewCards(), bookmarks.length ? [{
                section: 'Saved views (' + bookmarks.length + ')',
                title: 'Remove a bookmark\u2026', badge: bookmarks.length + ' kept',
                blurb: 'Choose one to take out of this genome.',
                books: removeCards,
            }] : [{ section: 'Saved views', note: true, title: 'No bookmarks yet. Frame a view on the chromosomes and keep it with the card above.', blurb: '' }]);
            try {
                exec('baja/lib/shelf.js', {
                    id: 'baja-karyo-bookmarks',
                    title: 'Bookmarked views',
                    subtitle: (bookmarks.length ? bookmarks.length + ' bookmark' + (bookmarks.length === 1 ? '' : 's') + ' kept  \u00b7  ' : '')
                        + 'Showing now: ' + suggested,
                    searchPlaceholder: 'Name for a new bookmark\u2026',
                    books: booksFor(''),
                    search: async (text) => booksFor(text),
                    graph: graph,
                });
            } catch (e) {
                step('bookmark shelf threw: ' + e);
                graph.setMessage(' Bookmarks could not be opened: ' + (e && e.message ? e.message : e) + ' ');
            }
        };

        const regionMenu = () => {
            const act = (label, fn) => ({
                label: label,
                ionFunction: createIonFunction(async () => {
                    try { hideAllModal(); } catch (e) { }
                    try { await fn(); } catch (e) {
                        step('region action threw: ' + e);
                        graph.setMessage(' That did not run: ' + (e && e.message ? e.message : e) + ' ');
                    }
                })
            });
            const span = regions.reduce((t, x) => t + (x.hi - x.lo), 0);
            // THE BUTTON THAT ONLY EXISTS WHEN THERE IS SOMETHING TO PRESS. With no
            // regions there is nothing to open, and an always-present control that
            // answers "choose a region first" is a control that lies about being ready.
            const loadRow = regions.length ? [
                act('Open ' + regions.length + ' selected region'
                    + (regions.length === 1 ? '' : 's') + ' in the editor', async () => {
                        await openRegions(regions.slice());
                    })
            ] : [];
            const head = regions.length
                ? (regions.length + ' region' + (regions.length === 1 ? '' : 's') + ' selected, '
                    + (Math.round(span / 1e4) / 100) + ' Mb in total')
                : 'No regions selected. Drag with <b>Select sequence</b>, or name one with '
                    + '<b>Find gene</b>, to choose regions.';
            // The two kinds of action in this menu answer to different things, and saying
            // so is cheaper than someone finding out by being surprised.
            const scope = 'Delete and Remove act on the selected regions. The highlights '
                + 'always cover the whole genome.';
            showModal({
                wid: 'card',
                data: {
                    // HEIGHT IS NOT OPTIONAL. Every card that shows in a modal in this
                    // application sets one; without it the card collapses and the modal
                    // opens with nothing in it, which is exactly what "the menu does not
                    // show up" looked like.
                    // The same inset the Find a gene panel uses: card_padding holds the
                    // panel off the modal edge, padding gives the rows their rhythm.
                    card_padding: '20px 22px',
                    padding: '7px 0',
                    height: '500px',
                    cards: [[
                        {
                            'title': ' ', 'width': '100%',
                            'component': {
                                wid: 'html',
                                data: '<div style="padding:2px 0 10px;font:14px Arial;">'
                                    + '<b>Regions</b><div style="color:#5b6b7a;font:12.5px Arial;'
                                    + 'margin-top:4px;">' + head + '</div>'
                                    + '<div style="color:#8296ab;font:11.5px Arial;'
                                    + 'margin-top:6px;">' + scope + '</div></div>'
                            }
                        },
                        {
                            'title': ' ', 'width': '100%',
                            'component': {
                                wid: 'mt-button',
                                data: {
                                    buttons: loadRow.concat([
                                        act('Delete all selected', () => {
                                            if (!regions.length) { graph.setMessage(' Choose a region first. '); return; }
                                            rebuildKeeping((ci, p) => !inRegion(ci, p), 'Deleted the selected regions');
                                        }),
                                        act('Remove all else', () => {
                                            if (!regions.length) { graph.setMessage(' Choose a region first. '); return; }
                                            rebuildKeeping((ci, p) => inRegion(ci, p), 'Kept only the selected regions');
                                        }),
                                        act('Label protein coding SNPs', () => applyFilter('coding', 1)),
                                        act('Highlight intronic', () => applyFilter('intronic', 2)),
                                        act("Highlight 3' UTR", () => applyFilter('three_utr', 3)),
                                        act("Highlight 5' UTR", () => applyFilter('five_utr', 4)),
                                        act('Highlight pathogenic / likely pathogenic',
                                            () => applyFilter('pathogenic', HL_PATHOGENIC)),
                                        act('Clear highlights', () => clearHighlights()),
                                        act('Clear regions', () => {
                                            regions = [];
                                            geneCache.clear();
                                            activeRegion = null;
                                            if (graph.wake) graph.wake();
                                            graph.setMessage(' Regions cleared. ');
                                        }),
                                    ])
                                }
                            }
                        },
                    ]]
                }
            });
        };

        // ---- the two toolbar menus ---------------------------------------------------
        //
        // Same shape as regionMenu above, which is this application's menu: a card in a
        // modal, a heading saying what the menu is for, then the rows. Written twice rather
        // than shared with regionMenu because the two differ in every line that matters and
        // a common builder would be a parameter for each of them.
        const menuAct = (label, fn) => ({
            label: label,
            ionFunction: createIonFunction(async () => {
                try { hideAllModal(); } catch (e) { }
                try { await fn(); } catch (e) {
                    step('menu action threw: ' + e);
                    try { graph.setMessage(' That did not run: ' + (e && e.message ? e.message : e) + ' '); } catch (e2) { }
                }
            })
        });

        const menuPanel = (title, blurb, buttons) => {
            showModal({
                wid: 'card',
                data: {
                    // HEIGHT IS NOT OPTIONAL -- see regionMenu. Without one the card
                    // collapses and the modal opens empty.
                    card_padding: '20px 22px',
                    padding: '7px 0',
                    height: '380px',
                    cards: [[
                        {
                            'title': ' ', 'width': '100%',
                            'component': {
                                wid: 'html',
                                data: '<div style="padding:2px 0 10px;font:14px Arial;">'
                                    + '<b>' + title + '</b><div style="color:#5b6b7a;font:12.5px Arial;'
                                    + 'margin-top:4px;">' + blurb + '</div></div>'
                            }
                        },
                        {
                            'title': ' ', 'width': '100%',
                            'component': { wid: 'mt-button', data: { buttons: buttons } }
                        }
                    ]]
                }
            });
        };

        // THE INFORMATION WINDOW, as in the editor: a floating panel that says what is loaded
        // and what is on, toggled by the Info button. Pinned lower-right, read-only, folds away
        // on a second press or its own ✕. Reads the live state each time it is opened.
        // ---- WHAT THE INFO PANEL CAN DO ABOUT WHAT IT SAYS ----------------------
        //
        // The panel listed what was loaded and stopped there, which left every obvious next
        // move somewhere else: to drop a file you reloaded the page, to find a region you
        // hunted for its band, to get the variants out you went to a menu that did not know
        // about them. A line that names a thing should be a way to act on that thing.
        //
        // Each row that refers to something real opens a shelf of what can be done to it.
        // The rows that are facts about the file -- species, genotypes, colour view -- stay
        // as text, because there is nothing to do to them from here.
        const dropSide = (sd) => {
            const nm = sideName(sd);
            const before = vtotal;
            rebuildKeeping((ci, pos, k) => {
                const d = vdata[ci];
                return ((d && d.side) ? d.side[k] : 0) !== sd;
            }, 'removed ' + nm);
            try { sideFile[sd] = ''; sideSlots[sd] = []; } catch (e) { }
            graph.setMessage(' ' + nm + ' removed \u2014 ' + (before - vtotal).toLocaleString()
                + ' variant' + ((before - vtotal) === 1 ? '' : 's') + ' taken off, '
                + vtotal.toLocaleString() + ' left. ');
        };
        // EVERYTHING LOADED, AS ONE TABLE. Position, alleles, class, which side it came from
        // and each sample's genotype. A whole genome is millions of rows and a browser will
        // not hand that to a spreadsheet, so it is capped and the cap is stated in the file
        // rather than left for the reader to notice a short table.
        const INFO_CSV_MAX = 200000;
        const dlAllVariantsCSV = () => {
            const rows = [];
            let dropped = 0;
            for (let ci = 0; ci < drawn.length; ci++) {
                const d = vdata[ci];
                if (!d || !d.n) continue;
                for (let k = 0; k < d.n; k++) {
                    if (rows.length >= INFO_CSV_MAX) { dropped++; continue; }
                    const ab = allelesAt(ci, k);
                    const row = { chrom: drawn[ci].name, pos: d.pos[k], ref: ab[0], alt: ab[1],
                        clinvar_class: CLS_SHORT[d.cls[k]] || '',
                        source: sideName((d.side ? d.side[k] : 0)),
                        name: (d.names && d.names[k]) || '' };
                    for (let si = 0; si < d.gtw && si < SAMPLES.length; si++) {
                        row[SAMPLES[si] || ('sample_' + (si + 1))] = GT_TEXT[gtOf(d, k, si)] || '';
                    }
                    rows.push(row);
                }
            }
            if (dropped) rows.push({ chrom: 'NOTE', pos: '', ref: '', alt: '',
                clinvar_class: '', source: '', name: 'capped at ' + INFO_CSV_MAX.toLocaleString()
                    + ' rows; ' + dropped.toLocaleString() + ' more are loaded' });
            return dlToCSV(rows);
        };
        const infoActions = (which) => {
            const books = [];
            const back = { section: 'Back', title: 'What is loaded', badge: 'info', icon: 'info_outline', back: true,
                ready: true, blurb: 'The rest of what this genome is carrying.', open: () => { try { infoPanel(true); } catch (e) { } } };
            if (which === 'vcfinfo') { try { vcfProfileMenu(lastVcfProfile); } catch (e) { } return; }
            if (which === 'sex') {
                books.push({ section: 'Sex', note: true, title: 'Each sample is judged on its own X heterozygosity and X read depth against its own autosomes, '
                    + 'on its Y calls outside the regions Y shares with X, and on whether the caller wrote haploid genotypes on X. '
                    + 'Where the signals disagree, the likely reason is named rather than a guess made.' });
                for (const x of sexSamples()) {
                    const res = sexCall(x.si);
                    books.push({ section: 'Sex', title: (x.nm || 'This file') + ': ' + res.call, icon: 'person', ready: true,
                        badge: res.confidence ? res.confidence + ' confidence' : 'no call',
                        swatch: res.call === 'male' ? '#60a5fa' : res.call === 'female' ? '#f472b6' : '#94a3b8',
                        blurb: (res.karyotype ? res.karyotype + '. ' : '') + res.why + '.' });
                }
                books.push(back);
                exec('baja/lib/shelf.js', { id: 'baja-karyo-analysis', title: 'Sex', subtitle: 'From X, Y, depth and ploidy in the loaded calls', graph: graph, books: books });
                return;
            }
            if (which === 'variants') {
                books.push({ section: 'Variants', note: true, title: vtotal.toLocaleString() + ' variant'
                    + (vtotal === 1 ? '' : 's') + ' on ' + vdata.filter((d) => d && d.n).length + ' chromosome(s).' });
                books.push({ section: 'Variants', accent: 'run', title: 'Download all information', badge: 'csv', icon: 'file_download', ready: vtotal > 0, readyNote: 'nothing loaded',
                    blurb: 'Every mark on the genome as one table: position, alleles, ClinVar class, which source it came from and each sample\'s genotype.'
                        + (vtotal > INFO_CSV_MAX ? ' Capped at ' + INFO_CSV_MAX.toLocaleString() + ' rows, and the file says so.' : ''),
                    open: () => { try { dlSaveText(dlAllVariantsCSV(), dlSafe(dlSpecies() + '_everything_loaded') + '.csv', 'text/csv'); dlMsg('Downloaded.'); } catch (e) { dlErr('Could not build the CSV: ' + (e && e.message ? e.message : e)); } } });
                books.push({ section: 'Variants', title: 'Zoom out to the whole genome', badge: 'view', icon: 'fit_screen', ready: true,
                    blurb: 'Frame every chromosome again.',
                    open: () => { try { goView(__genomeView()); } catch (e) { } } });
            } else if (which === 'sources') {
                const sc = sideCounts();
                const sides = [];
                if (sc.right) sides.push({ sd: 0, n: sc.right, where: 'right' });
                if (sc.left) sides.push({ sd: 1, n: sc.left, where: 'left' });
                books.push({ section: 'Sources', note: true, title: sides.length
                    ? 'Each file, paste or disease search that put marks on these chromosomes. Removing one takes its variants off and leaves the others alone.'
                    : 'Nothing is loaded.' });
                sides.forEach((x) => books.push({ section: 'Sources', title: sideName(x.sd),
                    badge: x.n.toLocaleString() + ' variants', icon: x.where === 'left' ? 'west' : 'east', ready: true,
                    blurb: 'Drawn on the ' + x.where + ' of every chromosome.',
                    books: () => [
                        { title: 'Remove this source', badge: 'takes it off', icon: 'delete_outline', ready: true,
                            blurb: 'Take its ' + x.n.toLocaleString() + ' variant(s) off the genome. Everything else stays, and the file on disk is untouched.',
                            open: () => { try { dropSide(x.sd); } catch (e) { } infoActions('sources'); } },
                        { title: 'Download its variants', badge: 'csv', icon: 'file_download', ready: true, accent: 'run',
                            blurb: 'This source only, as a table.',
                            open: () => { try { dlSaveText(dlToCSV(infoSideRows(x.sd)), dlSafe(dlSpecies() + '_' + sideName(x.sd)) + '.csv', 'text/csv'); dlMsg('Downloaded.'); } catch (e) { dlErr('Could not build the CSV: ' + (e && e.message ? e.message : e)); } } },
                    ] }));
            } else if (which === 'regions') {
                books.push({ section: 'Regions', note: true, title: (regions && regions.length)
                    ? regions.length + ' region(s) and bands on the chromosomes. A search puts one here for every gene it found.'
                    : 'No region is selected and nothing is banded.' });
                if (regions && regions.length) books.push({ section: 'Regions', title: 'Remove every one', badge: regions.length + '', icon: 'delete_outline', ready: true,
                    blurb: 'Clear the regions and the bands. The variants they sit over are left exactly as they are.',
                    open: () => { regions = []; activeRegion = null; if (graph.wake) graph.wake(); infoActions('regions'); } });
                (regions || []).slice(0, 200).forEach((rg) => {
                    const c = drawn[rg.i];
                    const where = (c ? c.name : '?') + ':' + human(rg.lo) + '-' + human(rg.hi);
                    books.push({ section: 'Regions', title: rg.label || rg.gene || where,
                        badge: rg.dz ? 'search' : (rg.lof ? 'result' : 'selected'),
                        swatch: rg.dz ? '#a855f7' : (rg.lof ? '#dc2626' : '#2563eb'), ready: true, blurb: where,
                        books: () => [
                            { title: 'Zoom into', badge: 'view', icon: 'zoom_in', ready: true, blurb: 'Frame ' + where + '.',
                                open: () => { try { const pad = Math.max((rg.hi - rg.lo) * 0.25, 2000) / MB; goView({ x0: barLeft(rg.i) - 0.5 * SLOT, x1: barRight(rg.i) + 0.5 * SLOT, y0: wy(rg.hi) - pad, y1: wy(rg.lo) + pad }); } catch (e) { } } },
                            { title: 'Remove', badge: 'region', icon: 'delete_outline', ready: true, blurb: 'Take this one off. Its variants stay.',
                                open: () => { const at = regions.indexOf(rg); if (at >= 0) regions.splice(at, 1); if (graph.wake) graph.wake(); infoActions('regions'); } },
                        ] });
                });
            } else if (which === 'bookmarks') {
                books.push({ section: 'Bookmarks', note: true, title: (bookmarks && bookmarks.length)
                    ? bookmarks.length + ' saved view(s).' : 'No view is bookmarked yet.' });
                (bookmarks || []).forEach((bm, i) => books.push({ section: 'Bookmarks', title: bm.name || ('View ' + (i + 1)),
                    badge: 'view', icon: 'bookmark', ready: true, blurb: 'Go back to this view, or drop it.',
                    books: () => [
                        { title: 'Go to it', badge: 'view', icon: 'zoom_in', ready: true, blurb: 'Frame it again.',
                            open: () => { try { goView({ x0: bm.x0, x1: bm.x1, y0: bm.y0, y1: bm.y1 }); } catch (e) { } } },
                        { title: 'Remove', badge: 'bookmark', icon: 'delete_outline', ready: true, blurb: 'Forget this view.',
                            open: () => { const at = bookmarks.indexOf(bm); if (at >= 0) bookmarks.splice(at, 1); if (graph.wake) graph.wake(); infoActions('bookmarks'); } },
                    ] }));
            } else if (which === 'samples') {
                books.push({ section: 'Samples', note: true, title: SAMPLES.length
                    ? 'Each genotype column in the loaded files. Glow one to see every variant it carries.'
                    : 'These files carry no genotype columns.' });
                SAMPLES.forEach((nm, si) => books.push({ section: 'Samples', title: nm || ('Sample ' + (si + 1)),
                    toggle: true, on: hlSamples.has(si), badge: hlSamples.has(si) ? 'glowing' : 'off',
                    swatch: SAMPLE_COLOR[si] || '#ee00ee', ready: true,
                    blurb: 'Glow every variant ' + (nm || 'this sample') + ' carries, right across the genome.',
                    open: () => { try { toggleSampleHighlight(si); } catch (e) { } infoActions('samples'); } }));
            } else if (which === 'patents') {
                books.push({ section: 'Patents', toggle: true, on: patOn, title: patOn ? 'Patent strip is shown' : 'Patent strip is off',
                    badge: patOn ? 'on' : 'off', icon: 'gavel', ready: true,
                    blurb: 'A strip down every chromosome showing where patented sequences fall.',
                    open: () => { try { patLoad(); } catch (e) { } infoActions('patents'); } });
            }
            books.push(back);
            exec('baja/lib/shelf.js', { id: 'baja-karyo-analysis', title: 'What is loaded',
                subtitle: which, graph: graph, books: books });
        };
        const infoSideRows = (sd) => {
            const rows = [];
            for (let ci = 0; ci < drawn.length; ci++) {
                const d = vdata[ci];
                if (!d || !d.n) continue;
                for (let k = 0; k < d.n; k++) {
                    if ((d.side ? d.side[k] : 0) !== sd) continue;
                    if (rows.length >= INFO_CSV_MAX) break;
                    const ab = allelesAt(ci, k);
                    rows.push({ chrom: drawn[ci].name, pos: d.pos[k], ref: ab[0], alt: ab[1],
                        clinvar_class: CLS_SHORT[d.cls[k]] || '', name: (d.names && d.names[k]) || '' });
                }
            }
            return rows;
        };
        const infoPanel = (reopen) => {
            const id = 'baja-karyo-info';
            try {
                const ex = document.getElementById(id);
                // Clicking the toolbar button again closes it; coming BACK from one of its
                // own action shelves has to reopen it, not toggle it shut.
                if (ex && ex.parentNode) { ex.parentNode.removeChild(ex); if (!reopen) return; }
            } catch (e) { }
            const esc = (s) => ('' + (s == null ? '' : s)).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
            const nS = SAMPLES.length;
            const chromsWith = vdata.reduce((a, d) => a + (d && d.n ? 1 : 0), 0);
            const hasGt = vdata.some(d => d.gtw && d.gts);
            let curName = '';
            try { const c = '' + ((window.history.state || {}).karyotype || ''); curName = c ? c.split('/').filter(Boolean).pop() : ''; } catch (e) { }
            const modeName = { class: 'ClinVar class', sample: 'by sample', phase: 'by phase' }[colorMode] || colorMode;
            // What is glowing / highlighted right now.
            let hlStr = 'none';
            try {
                if (hlSamples && hlSamples.size) {
                    hlStr = 'samples ' + Array.from(hlSamples).map((si) => SAMPLES[si] || ('#' + (si + 1))).join(', ');
                } else if (hlActive) {
                    hlStr = HL_NAME[hlActive] || 'on';
                }
            } catch (e) { }
            const rows = [
                ['File', curName || 'not saved yet'],
                ['Species', (r && r.species) || 'human'],
                ['Variants', (vtotal || 0).toLocaleString(), 'variants'],
                ['Chromosomes with variants', chromsWith + ' of ' + drawn.length],
                ['Samples', nS ? (nS + ' — ' + SAMPLES.join(', ')) : 'none', nS ? 'samples' : ''],
                // WHAT PUT THESE MARKS HERE. Samples come from a VCF's genotype columns, and a
                // sites-only source -- ClinVar, and so the disease loader -- has none, so the
                // row above says 'none' however much is on the chromosomes. The side names are
                // the other half of that answer, and the only place a disease load is named.
                ['Sources', (function () {
                    try {
                        const sc = sideCounts();
                        const out = [];
                        if (sc.right) out.push(sideName(0) + ' (' + sc.right.toLocaleString() + ')');
                        if (sc.left) out.push(sideName(1) + ' (' + sc.left.toLocaleString() + ', left)');
                        return out.length ? esc(out.join('  ·  ')) : 'nothing loaded';
                    } catch (e) { return 'nothing loaded'; }
                })(), 'sources'],
                ['Genotypes', hasGt ? (lastVcfProfile && lastVcfProfile.phased ? 'yes, phased' : 'yes') : 'no'],
                ['Sex', (() => {
                    try {
                        const xs = sexSamples();
                        if (!xs.length) return 'nothing loaded';
                        return esc(xs.slice(0, 4).map((x) => (x.nm ? x.nm + ': ' : '') + sexWord(sexCall(x.si))).join('  ·  '));
                    } catch (e) { return 'could not be read'; }
                })(), 'sex'],
                // WHAT THE FILE TURNED OUT TO BE, kept where it can be found again: the
                // prompt at load time is a moment, and the answer is wanted later too.
                ['About the file', lastVcfProfile
                    ? esc(lastVcfProfile.kind + (lastVcfProfile.phased ? ', phased' : ''))
                    : 'no VCF read this session', lastVcfProfile ? 'vcfinfo' : ''],
                ['Color view', modeName],
                ['Highlighting', esc(hlStr)],
                ['Regions selected', '' + ((regions && regions.length) || 0), 'regions'],
                ['Bookmarks', '' + ((bookmarks && bookmarks.length) || 0), 'bookmarks'],
                ['Patents', patOn ? ('shown' + (patNote ? ' — ' + patNote : '')) : 'off', 'patents'],
            ];
            const panel = document.createElement('div');
            panel.id = id;
            panel.style.cssText = 'position:fixed;right:14px;bottom:14px;z-index:2147482000;width:290px;'
                + 'max-height:70vh;display:flex;flex-direction:column;background:#0b2545;color:#e8f0fb;'
                + 'border:1px solid rgba(255,255,255,0.16);border-radius:12px;box-shadow:0 10px 34px rgba(0,0,0,0.45);'
                + 'font-family:Arial,Helvetica,sans-serif;overflow:hidden;';
            const header = document.createElement('div');
            header.style.cssText = 'flex:0 0 auto;display:flex;align-items:center;gap:8px;padding:10px 12px;'
                + 'background:#0a1e3a;border-bottom:1px solid rgba(255,255,255,0.12);';
            header.innerHTML = '<span style="font-size:15px;line-height:1;">ℹ️</span>'
                + '<span style="font:700 13px Arial;flex:1;">Karyotype info</span>'
                + '<button id="ki-x" title="Close" style="cursor:pointer;border:none;background:transparent;color:#9fb3c8;font:700 14px Arial;line-height:1;padding:2px 6px;">✕</button>';
            const body = document.createElement('div');
            body.style.cssText = 'flex:1 1 auto;overflow:auto;padding:10px 12px;font:12.5px Arial;line-height:1.5;';
            // A ROW THAT NAMES SOMETHING IS A WAY TO ACT ON IT. The ones carrying an action
            // key take a pointer and a chevron; the rest are facts about the file and stay as
            // text, because there is nothing to do to "species" from here.
            body.innerHTML = rows.map((rw, i) => {
                const act = rw[2] || '';
                return '<div data-act="' + esc(act) + '" data-i="' + i + '" style="display:flex;gap:10px;padding:3px 0;'
                    + 'border-bottom:1px solid rgba(255,255,255,0.06);'
                    + (act ? 'cursor:pointer;border-radius:6px;margin:0 -4px;padding-left:4px;padding-right:4px;' : '')
                    + '">'
                    + '<span style="flex:0 0 46%;color:' + (act ? '#8fd3ff' : '#9fb3c8') + ';">' + esc(rw[0]) + '</span>'
                    + '<span style="flex:1;text-align:right;font-weight:600;word-break:break-word;">' + esc(rw[1])
                    + (act ? '<span style="color:#8fd3ff;margin-left:6px;">\u203a</span>' : '') + '</span></div>';
            }).join('');
            try {
                Array.prototype.forEach.call(body.querySelectorAll('[data-act]'), (el) => {
                    const act = el.getAttribute('data-act');
                    if (!act) return;
                    el.onmouseenter = () => { el.style.background = 'rgba(143,211,255,0.12)'; };
                    el.onmouseleave = () => { el.style.background = ''; };
                    el.onclick = () => { try { close(); } catch (e) { } try { infoActions(act); } catch (e2) { } };
                });
            } catch (e) { }
            panel.appendChild(header);
            panel.appendChild(body);
            document.body.appendChild(panel);
            const close = leaveWithKaryotype(panel);
            try { header.querySelector('#ki-x').onclick = () => close(); } catch (e) { }
        };

        // COLOR IS A LIBRARY OF THREE. The same shelf as Search and Files: one card per
        // mode, the one that is on badged so, the ones the file cannot support greyed
        // with the reason rather than missing.
        const colorMenu = () => {
            if (!vtotal) { graph.setMessage(' Load a VCF first: there are no variants to color. '); return; }
            const nS = SAMPLES.length;
            const modeBadge = (m) => (colorMode === m ? 'on' : 'off');
            // Choosing a color scheme; clicking the one already on turns it off (back to the
            // default ClinVar-class colors). Reopens so the on/off badges refresh.
            const setMode = (m) => {
                try { setColorMode((colorMode === m && m !== 'class') ? 'class' : m); } catch (e) { }
                colorMenu();
            };
            // ONE BUTTON to flip the whole karyotype between its color views without hunting
            // for the individual scheme card. It cycles through the schemes the file can
            // actually show: ClinVar class always, and by-sample / by-phase when there are
            // samples. Its badge names the view that is on now.
            // SAMPLE COLOR OPTIONS ARE FOR MULTI-SAMPLE FILES. One sample (or none) is just
            // plotted -- every carried variant is that one sample, so "which sample carries it"
            // has no answer worth a color. `multi` gates the by-sample scheme, the per-sample
            // color pickers and the per-sample glow. ClinVar class is always offered, and the
            // by-phase (haplotype) view is offered whenever the file carries genotypes, since
            // that reads a single sample too.
            const hasGt = vdata.some(d => d.gtw && d.gts);
            const multi = nS > 1;
            const schemeLabel = { class: 'ClinVar class', sample: 'By sample', phase: 'By phase' };
            const SCHEMES = ['class'].concat(multi ? ['sample'] : []).concat(hasGt ? ['phase'] : []);
            const cycleColorView = () => {
                const i = SCHEMES.indexOf(colorMode);
                const next = SCHEMES[(i + 1) % SCHEMES.length];
                try { setColorMode(next); } catch (e) { }
                try { graph.setMessage(' Color view: ' + (schemeLabel[next] || next) + '. '); } catch (e) { }
                colorMenu();
            };
            // The annotation highlights, now here as on/off toggles as well as under Search.
            // hlActive holds the one that is on; clicking it again clears it.
            const hlBadge = (code) => (hlActive === code ? 'on' : 'off');
            const toggleHl = async (kind, code) => {
                try { if (hlActive === code) { clearHighlights(); } else { await applyFilter(kind, code); } } catch (e) { }
                colorMenu();
            };
            // One card per sample: glow every variant that sample carries, genome-wide, in the
            // sample's own color. Each toggles on and off ON ITS OWN, so several samples can
            // glow at once. Multi-sample only; needs genotypes.
            const sampleGlowCards = (multi && hasGt) ? SAMPLES.map((nm, si) => ({
                section: 'By sample (glowing)',
                title: nm || ('Sample ' + (si + 1)),
                badge: hlSamples.has(si) ? 'on' : 'off', toggle: true, on: hlSamples.has(si),
                blurb: 'Glow every variant ' + (nm || ('sample ' + (si + 1))) + ' carries, right across the genome.'
                    + (hlSamples.has(si) ? ' Click to turn it off.' : ''),
                open: () => {
                    try { toggleSampleHighlight(si); } catch (e) { }
                    colorMenu();
                },
            })) : (multi ? [{
                section: 'By sample (glowing)', title: 'No genotypes in this VCF', badge: '',
                ready: false, readyNote: 'no genotypes',
                blurb: 'This VCF has sample columns but no genotype calls, so per-sample glow is not available.',
                open: () => { },
            }] : []);
            // CHOOSE A SAMPLE'S COLOR. A native color picker, opened from within the card's
            // click so the browser still counts it as a user gesture. The chosen color is
            // written into SAMPLE_COLOR (read live by colorOf, the density palette, the legend
            // and the glow), the canvas is woken, and if that sample is glowing now its glow
            // color is updated too. The choice travels with the file (see stateDoc).
            const pickSampleColor = (si) => {
                try {
                    const inp = document.createElement('input');
                    inp.type = 'color';
                    inp.value = SAMPLE_COLOR[si] || '#1d9bf0';
                    // Anchored to the CENTER of the screen, not parked off-screen: the OS color
                    // dialog opens next to its input, so an input at left:-9999px opened the
                    // picker off the right edge. A 1px, invisible input in the middle puts the
                    // dialog in the middle.
                    inp.style.cssText = 'position:fixed;left:50%;top:50%;transform:translate(-50%,-50%);'
                        + 'width:1px;height:1px;opacity:0;border:0;padding:0;margin:0;z-index:2147483647;';
                    document.body.appendChild(inp);
                    inp.addEventListener('change', () => {
                        const c = ('' + inp.value).trim();
                        if (/^#[0-9a-fA-F]{6}$/.test(c)) {
                            SAMPLE_COLOR[si] = c;
                            if (hlSamples.has(si)) { HL_COLOR[SAMPLE_HL_BASE + si] = c; if (graph.wake) graph.wake(); }
                            try { if (graph.wake) graph.wake(); } catch (e) { }
                            try { if (colorMode === 'sample') legendShow(); } catch (e) { }
                            try { graph.setMessage(' ' + (SAMPLES[si] || ('Sample ' + (si + 1))) + ' is now ' + c + '. '); } catch (e) { }
                        }
                        try { if (inp.parentNode) inp.parentNode.removeChild(inp); } catch (e) { }
                        colorMenu();
                    }, { once: true });
                    inp.click();
                } catch (e) {
                    try { graph.setMessage(' The color picker could not open. '); } catch (e2) { }
                }
            };
            const sampleColorCards = multi ? SAMPLES.map((nm, si) => ({
                section: 'Sample colors',
                title: nm || ('Sample ' + (si + 1)),
                swatch: SAMPLE_COLOR[si] || '#1d9bf0',
                badge: (SAMPLE_COLOR[si] || '').toUpperCase(),
                blurb: 'Pick the color for ' + (nm || ('sample ' + (si + 1)))
                    + ' — used in the by-sample view, its glow, and the legend.',
                open: () => pickSampleColor(si),
            })) : [];
            try {
                exec('baja/lib/shelf.js', {
                    id: 'baja-karyo-color',
                    title: 'Color & highlight',
                    subtitle: multi ? ('This VCF has ' + nS + ' samples: ' + SAMPLES.join(', ') + '.')
                        : (nS === 1
                            ? ('One sample (' + SAMPLES[0] + '): variants are plotted by ClinVar class'
                                + (hasGt ? ', with a haplotype view available' : '') + '.')
                            : 'This VCF carries no sample columns, so its variants are plotted by ClinVar class.'),
                    books: [
                        // The toggle only earns its place when there is more than one view to
                        // flip between; a single-sample file with no phase has only ClinVar class.
                        ...(SCHEMES.length > 1 ? [{
                            section: 'Color view', title: 'Toggle color view', icon: '🎨',
                            badge: (schemeLabel[colorMode] || colorMode),
                            blurb: 'Flip the whole karyotype through its color views — '
                                + SCHEMES.map((s) => schemeLabel[s] || s).join(', ')
                                + '. Now showing ' + (schemeLabel[colorMode] || colorMode) + '.',
                            open: () => cycleColorView(),
                        }] : []),
                        {
                            section: 'Color scheme', title: 'By ClinVar class', badge: modeBadge('class'), toggle: true, on: colorMode === 'class',
                            blurb: 'Pathogenic red, benign green, uncertain amber, conflicting grey; unclassified in magenta.',
                            open: () => setMode('class'),
                        },
                        // By sample only for a multi-sample VCF; a single-sample file is just
                        // plotted (ClinVar class), which is what the user asked for.
                        ...(multi ? [{
                            section: 'Color scheme', title: 'By sample', badge: modeBadge('sample'), toggle: true, on: colorMode === 'sample',
                            blurb: 'Which sample carries the change: ' + SAMPLES.join(', ')
                                + '. Slate where more than one does, pale where none does.',
                            open: () => setMode('sample'),
                        }] : []),
                        // By phase whenever there are genotypes — a haplotype view reads a
                        // single sample as well as several.
                        ...(hasGt ? [{
                            section: 'Color scheme', title: 'By phase', badge: modeBadge('phase'), toggle: true, on: colorMode === 'phase',
                            blurb: 'Haplotype 1 blue, haplotype 2 pink, homozygous purple, unphased heterozygous amber.',
                            open: () => setMode('phase'),
                        }] : []),
                        // The annotation highlights: each turns on and off, and only one is on at
                        // a time (a variant shows one mark). The same set the Search window offers.
                        { section: 'Highlight (annotation)', title: 'Protein coding', badge: hlBadge(1), toggle: true, on: hlActive === 1, blurb: 'Mark the variants in coding sequence, genome-wide.', open: () => toggleHl('coding', 1) },
                        { section: 'Highlight (annotation)', title: 'Intronic', badge: hlBadge(2), toggle: true, on: hlActive === 2, blurb: 'Mark the variants that fall in introns.', open: () => toggleHl('intronic', 2) },
                        { section: 'Highlight (annotation)', title: "3' UTR", badge: hlBadge(3), toggle: true, on: hlActive === 3, blurb: "Mark the variants in 3' untranslated regions.", open: () => toggleHl('three_utr', 3) },
                        { section: 'Highlight (annotation)', title: "5' UTR", badge: hlBadge(4), toggle: true, on: hlActive === 4, blurb: "Mark the variants in 5' untranslated regions.", open: () => toggleHl('five_utr', 4) },
                        { section: 'Highlight (annotation)', title: 'Pathogenic / likely pathogenic', badge: hlBadge(HL_PATHOGENIC), toggle: true, on: hlActive === HL_PATHOGENIC, blurb: 'Mark the variants ClinVar calls pathogenic or likely pathogenic.', open: () => toggleHl('pathogenic', HL_PATHOGENIC) },
                        ...sampleGlowCards,
                        ...sampleColorCards,
                        { section: 'Highlight (annotation)', title: 'Clear highlights', badge: hlActive ? 'on' : '', ready: !!hlActive, readyNote: 'nothing highlighted', blurb: 'Take every mark off and draw the variants in their own colors again.', open: () => { try { clearHighlights(); } catch (e) { } colorMenu(); } },
                    ],
                    graph: graph,
                });
            } catch (e) {
                step('color shelf threw: ' + e);
                graph.setMessage(' Color could not be opened: ' + (e && e.message ? e.message : e) + ' ');
            }
        };

        // FILES IS A LIBRARY TOO, the same shelf Search opens: four cards that say what
        // they do, under a subtitle that says which file this is and what is on it. The
        // shelf reports a card that throws, so a save that fails is a message rather
        // than a dead button.
        // Clear everything loaded and start from an empty karyotype (same species, no
        // variants). Confirms first when there is anything to lose.
        const newKaryotype = async () => {
            let ok = true;
            if (vtotal || (regions && regions.length) || (bookmarks && bookmarks.length)) {
                try {
                    ok = await exec('baja/lib/confirm-leave.js', {
                        title: 'Start a new genome?',
                        message: 'This clears every variant, region and bookmark now loaded. Save first if you want to keep them.',
                        confirmLabel: 'Start fresh'
                    });
                } catch (e) { ok = false; }
            }
            if (!ok) return;
            for (let ci = 0; ci < drawn.length; ci++) {
                const d = vdata[ci];
                d.n = 0; d.pos = new Float64Array(0); d.cls = new Uint8Array(0);
                d.ref = new Uint8Array(0); d.alt = new Uint8Array(0);
                d.cplx = new Map(); d.names = []; d.snps = [];
                d.gts = null; d.gtw = 0; d.baf = null; d.hl = new Uint8Array(0); d.hlIdx = [];
                d.side = new Uint8Array(0); d.nL = 0; d.histL = null;
                d.hist = new Uint32Array(HIST_BINS); d.histBy = null;
            }
            vtotal = 0; vobjects = 0;
            gtSilent = null;
            sideFile[0] = ''; sideFile[1] = '';
            SIDE_LABEL[0] = ''; SIDE_LABEL[1] = '';
            sideSlots[0] = []; sideSlots[1] = [];
            regions = []; try { geneCache.clear(); } catch (e) { }
            bookmarks = []; activeRegion = null; hlActive = 0;
            try { SAMPLES.length = 0; SAMPLE_VCF.length = 0; SEX_EV.length = 0; } catch (e) { }
            try { setColorMode('class'); } catch (e) { }
            try { reindexHighlights(); } catch (e) { }
            try { const nav = document.getElementById('baja-karyo-booknav'); if (nav && nav.parentNode) nav.parentNode.removeChild(nav); } catch (e) { }
            try { window.history.replaceState({ karyotype: '' }, 'karyotype', '/app/manchester/karyotype'); } catch (e) { }
            try { if (graph.wake) graph.wake(); } catch (e) { }
            try { await fit(); pan(); } catch (e) { }
            graph.setMessage(' Started fresh — the genome is empty. Load a VCF to add variants. ');
        };

        const filesMenu = () => {
            let cur = '';
            try { cur = '' + ((window.history.state || {}).karyotype || ''); } catch (e) { cur = ''; }
            const curName = cur ? cur.split('/').filter(Boolean).pop() : '';
            const onIt = vtotal
                ? vtotal.toLocaleString() + ' variant' + (vtotal === 1 ? '' : 's')
                    + (regions.length ? ', ' + regions.length + ' region' + (regions.length === 1 ? '' : 's') + ' selected' : '')
                : 'no variants loaded';
            try {
                exec('baja/lib/shelf.js', {
                    id: 'baja-karyo-files',
                    title: 'Karyotype files',
                    subtitle: (curName ? curName + '  ·  ' : 'Not saved yet  ·  ') + onIt,
                    // SAVE COMES FIRST. It is the card people open this menu for, and the one
                    // that costs something to miss; the others are recoverable. Each card wears
                    // a Material icon so the action reads before the title does -- the floppy
                    // is the save glyph every toolbar uses.
                    books: [
                        {
                            title: curName ? 'Save this genome' : 'Save this genome as…',
                            badge: curName ? 'saved as ' + curName : 'unsaved',
                            icon: 'save',
                            blurb: 'Keep this genome, its variants and the selected regions in My Files, to reopen later or share by link.',
                            open: () => saveJson(),
                            ready: !!vtotal || !!regions.length,
                            readyNote: 'nothing to save yet',
                        },
                        {
                            title: 'Open a saved genome', badge: 'My Files', icon: 'folder_open',
                            blurb: 'Browse My Files and open a genome you kept. A .baja file there opens in the editor instead.',
                            open: () => openJson(false),
                        },
                        {
                            title: 'New…', badge: 'clear', icon: 'add',
                            blurb: 'Clear the variants, regions and bookmarks loaded now and start from an empty karyotype. Asks first if there is anything to lose.',
                            open: () => newKaryotype(),
                        },
                        {
                            title: 'Remove a saved genome', badge: 'My Files', icon: 'delete_outline',
                            blurb: 'Browse My Files and delete a genome you no longer need. Asked before each one; it is not moved to a bin.',
                            open: () => openJson(true),
                        },
                    ],
                    graph: graph,
                });
            } catch (e) {
                step('files shelf threw: ' + e);
                graph.setMessage(' Files could not be opened: ' + (e && e.message ? e.message : e) + ' ');
            }
        };

        // UPLOAD IS A LIBRARY OF THE KINDS OF FILE IT TAKES. The button used to open the
        // picker straight away, which meant the only place that said what could be
        // uploaded was the tooltip. One card per kind, each opening the picker filtered
        // to it, and a card for anything else; the reader still decides from the bytes.
        // ---- A DISEASE, AS MUTATIONS ON THE GENOME --------------------------------------
        //
        // Type a condition; get its pathogenic variants placed on the chromosomes. The
        // editor already answers this question for one transcript, and the route it takes is
        // the one worth copying, because the obvious route is wrong: a model asked to recall
        // which mutations characterise a disease produces plausible, non-existent variants
        // with plausible, wrong coordinates, and nothing downstream can tell them from real
        // ones.
        //
        // So the model is asked ONLY which OMIM phenotype the words mean -- a small question
        // with a checkable answer -- and py/bio/omim-variants.py checks every MIM it proposes
        // against an index built from ClinVar itself, dropping any that is not in it. The
        // genes come back from that index, and the variants come from the ClinVar VCF by
        // genomic region. Every mark placed here is a real record at a real coordinate.
        //
        // NONE OF THAT IS SHOWN. The MIM numbers, the phenotype names, the per-phenotype
        // record counts are all machinery, and putting them on screen asks the reader to
        // audit a lookup they did not make. What is said is the disease, the genes, and how
        // many mutations landed.
        let dzBusy = false;
        let dzLast = '';
        // PAST THIS MANY, ASK. Drawing every pathogenic record a gene or a condition carries
        // answers a broader question than the one that was asked, and a chromosome painted
        // with all of them says less than one painted with the ones that matter.
        const DZ_PROMPT = 50;
        // THE CHOICE, MADE INSIDE THE PANEL the question was asked in. The subsets are
        // counted from the records themselves, so every option on offer is one that exists
        // and none of them can come back empty. A suggestion sits at the top when one can be
        // had; it is a recommendation over the same counted list, and the manual options are
        // there whether it arrives or not.
        const dzChoose = (disease, rows, meta, say, arm, panel) => new Promise((resolve) => {
            const host = panel && panel.querySelector('#dz-choose-host');
            if (!host) { resolve({ keep: null }); return; }
            const esc2 = (t) => ('' + (t == null ? '' : t)).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
            const tally = (fn) => {
                const m = new Map();
                for (const r of meta) { for (const v of [].concat(fn(r) || [])) { if (v) m.set(v, (m.get(v) || 0) + 1); } }
                return Array.from(m.entries()).sort((a, b) => b[1] - a[1]);
            };
            const byGene = tally((r) => r.gene);
            const bySig = tally((r) => r.sig);
            const byPhen = tally((r) => r.phen).slice(0, 24);
            let done = false;
            const finish = (v) => { if (done) return; done = true; try { host.innerHTML = ''; host.style.display = 'none'; } catch (e) { } resolve(v); };
            const BTN = 'cursor:pointer;border-radius:8px;padding:10px 16px;font:700 13px Arial;border:1px solid #12c2e0;background:#12c2e0;color:#042a33;';
            const GHOST = 'cursor:pointer;border-radius:8px;padding:10px 16px;font:600 13px Arial;border:1px solid rgba(255,255,255,0.25);background:transparent;color:#eaf6f9;';
            const OPT = 'cursor:pointer;text-align:left;width:100%;box-sizing:border-box;border-radius:9px;padding:11px 14px;'
                + 'font:600 13px Arial;border:1px solid rgba(255,255,255,0.16);background:#0a1e3a;color:#eaf6f9;margin-top:8px;';
            const optionRows = (kind, list) => list.map((kv) =>
                '<button class="dz-opt" data-kind="' + kind + '" data-val="' + esc2(kv[0]) + '" style="' + OPT + '">'
                + esc2(kv[0]) + '<span style="float:right;color:#9fb3c8;font-weight:600;">' + kv[1].toLocaleString() + '</span></button>').join('');
            const wire = () => {
                try {
                    Array.prototype.forEach.call(host.querySelectorAll('.dz-opt'), (b) => {
                        b.onclick = () => {
                            const kind = b.getAttribute('data-kind'), val = b.getAttribute('data-val');
                            finish({ keep: (r) => (kind === 'gene' ? r.gene === val
                                : (kind === 'significance' ? r.sig === val
                                    : [].concat(r.phen || []).indexOf(val) >= 0)) });
                        };
                    });
                    const all = host.querySelector('#dz-all'); if (all) all.onclick = () => finish({ keep: null });
                    const cx = host.querySelector('#dz-cancel'); if (cx) cx.onclick = () => finish(null);
                } catch (e) { }
            };
            const showOptions = (rec) => {
                host.innerHTML = ''
                    + '<div style="font:700 15px Arial;margin-bottom:4px;">Narrow ' + rows.length.toLocaleString() + ' mutations</div>'
                    + (rec && rec.why ? '<div style="font:12.5px/1.6 Arial;color:#9fd3ff;margin:8px 0 2px;">' + esc2(rec.why) + '</div>' : '')
                    + (rec && rec.values && rec.values.length
                        ? '<div style="font:11px Arial;color:#9fb3c8;margin-top:10px;text-transform:uppercase;letter-spacing:1.2px;">Suggested</div>'
                          + rec.values.map((v) => { const c = (rec.kind === 'gene' ? byGene : rec.kind === 'significance' ? bySig : byPhen)
                              .filter((kv) => kv[0] === v); return optionRows(rec.kind, c.length ? c : [[v, 0]]); }).join('')
                        : '')
                    + (byGene.length > 1 ? '<div style="font:11px Arial;color:#9fb3c8;margin-top:16px;text-transform:uppercase;letter-spacing:1.2px;">By gene</div>' + optionRows('gene', byGene.slice(0, 12)) : '')
                    + (bySig.length > 1 ? '<div style="font:11px Arial;color:#9fb3c8;margin-top:16px;text-transform:uppercase;letter-spacing:1.2px;">By classification</div>' + optionRows('significance', bySig) : '')
                    + (byPhen.length > 1 ? '<div style="font:11px Arial;color:#9fb3c8;margin-top:16px;text-transform:uppercase;letter-spacing:1.2px;">By condition on the record</div>' + optionRows('phenotype', byPhen.slice(0, 12)) : '')
                    + '<div style="display:flex;gap:10px;margin-top:20px;">'
                    + '<button id="dz-all" style="' + GHOST + '">Load all ' + rows.length.toLocaleString() + '</button>'
                    + '<button id="dz-cancel" style="' + GHOST + '">Cancel</button></div>';
                wire();
            };
            host.style.display = 'block';
            host.innerHTML = ''
                + '<div style="font:700 15px Arial;">' + rows.length.toLocaleString() + ' pathogenic mutations found</div>'
                + '<div style="font:12.5px/1.6 Arial;color:#9fb3c8;margin-top:6px;">That is a lot to read at once. '
                + 'They can all go on, or you can keep the part of them this is really about.</div>'
                + '<div style="display:flex;gap:10px;margin-top:16px;">'
                + '<button id="dz-all" style="' + BTN + '">Load all ' + rows.length.toLocaleString() + '</button>'
                + '<button id="dz-narrow" style="' + GHOST + '">Narrow it down</button>'
                + '<button id="dz-cancel" style="' + GHOST + '">Cancel</button></div>';
            wire();
            try {
                host.querySelector('#dz-narrow').onclick = async () => {
                    host.innerHTML = '<div style="font:12.5px Arial;color:#9fb3c8;">Weighing what these records cover…</div>';
                    let rec = null;
                    try {
                        const em2 = new EngineMonitor((m) => { try { say(m); } catch (e) { } });
                        const rs = await exec(server + '/py/bio/refine-variant-set.py', em2, JSON.stringify({
                            disease: disease, total: rows.length,
                            genes: byGene, significances: bySig, phenotypes: byPhen }));
                        if (rs && rs.ok) {
                            let vals = []; try { vals = JSON.parse(rs.values || '[]'); } catch (e) { vals = []; }
                            rec = { kind: '' + (rs.kind || ''), values: vals, why: '' + (rs.why || '') };
                        }
                    } catch (e) { rec = null; }
                    showOptions(rec);
                };
            } catch (e) { }
        });
        const DZ_MAX_GENES = 8;          // genes to read per disease
        const DZ_MAX_PER_GENE = 4000;    // ClinVar records taken from one gene
        // A record has to be pathogenic to be worth drawing. ClinVar's own wording is what
        // is tested, not a tidied copy of it: "Pathogenic/Likely_pathogenic" and
        // "Likely_pathogenic" both count, "Conflicting_classifications_of_pathogenicity"
        // does not -- a variant the submitters disagree about is not a finding.
        // clinsig comes back as an ARRAY -- a record can carry several classifications --
        // so it is joined rather than coerced. '' + ['a','b'] happens to give 'a,b' and
        // would have worked by accident here; relying on that is how a later record with
        // one classification and a nested array starts reading as '[object Object]'.
        const dzSig = (v) => {
            const c = v && v.clinsig;
            return (Array.isArray(c) ? c.join(', ') : ('' + (c == null ? '' : c)));
        };
        const dzIsPathogenic = (v) => {
            const t = dzSig(v).toLowerCase();
            if (!t) return false;
            if (t.indexOf('conflict') >= 0) return false;
            return t.indexOf('pathogenic') >= 0;
        };
        // READ THE WHOLE GENE, NOT THE FIRST 5,000 RECORDS OF IT.
        //
        // read-vcf-variants.py stops at MAX_ROWS = 5000 per call and walks the region in
        // position order, so a gene denser than that is not sampled -- it is CUT, at a
        // coordinate, with everything past it missing. CFTR's own span returns exactly 5000,
        // which is how this was caught: a round number is never a count.
        //
        // A window that comes back at the cap is therefore not trusted. It is halved and both
        // halves read, so density decides the depth rather than a guess at it, and a gene that
        // fits in one call still costs exactly one call.
        const DZ_ROW_CAP = 5000;     // must match MAX_ROWS in read-vcf-variants.py
        const DZ_SPLIT_MAX = 6;      // up to 64 windows for one gene
        const dzFetch = async (chrBare, lo, hi, depth) => {
            const em2 = new EngineMonitor(() => { });
            let vs = [];
            try {
                const rv = await exec(server + '/py/bio/read-vcf-variants.py', em2, 'clinvar',
                    chrBare, '' + lo, '' + hi);
                vs = JSON.parse((rv && rv.variants) || '[]');
            } catch (e) { vs = []; }
            if (vs.length < DZ_ROW_CAP || depth >= DZ_SPLIT_MAX || hi - lo < 2) return vs;
            const mid = Math.floor((lo + hi) / 2);
            const a = await dzFetch(chrBare, lo, mid, depth + 1);
            const b = await dzFetch(chrBare, mid + 1, hi, depth + 1);
            return a.concat(b);
        };
        const dzRun = async (text, panel) => {
            const query = ('' + (text || '')).trim();
            if (!query) return;
            if (dzBusy) return;
            dzBusy = true;
            // A LINE THAT DOES NOT MOVE READS AS A LINE THAT HAS STOPPED.
            //
            // The slow parts of this are two server round trips that think for several
            // seconds and say nothing while they do. A status line holding the same words
            // for eight seconds is indistinguishable from one that has hung, and the only
            // thing the user can do about it is press the button again.
            //
            // So the line breathes: dots that cycle twice a second, and past three seconds
            // the elapsed count, which is the part that says "still going" rather than
            // "still here". Only the panel's own line animates -- the message bar under the
            // chromosomes is set once per real step, because redrawing that twice a second
            // for the whole genome is a cost paid for nothing.
            let beatTimer = null, beatBase = '', beatAt = 0;
            const beatStop = () => { try { if (beatTimer) clearInterval(beatTimer); } catch (e) { } beatTimer = null; };
            const beatDraw = () => {
                try {
                    const el = panel && panel.querySelector('#dz-status');
                    if (!el) return;
                    const ms = Date.now() - beatAt;
                    el.textContent = beatBase + '.'.repeat(1 + (Math.floor(ms / 500) % 3))
                        + (ms >= 3000 ? '   ' + Math.round(ms / 1000) + 's' : '');
                } catch (e) { }
            };
            const say = (m) => {
                try { graph.setMessage(' ' + m + ' '); } catch (e) { }
                beatBase = ('' + m).replace(/[.\u2026\s]+$/, '');
                beatAt = Date.now();
                beatStop();
                beatDraw();
                try { beatTimer = setInterval(beatDraw, 500); } catch (e) { }
            };
            const fail = (m) => {
                beatStop();
                try { graph.setError(' ' + m + ' ', 12); } catch (e) { }
                try {
                    const el = panel && panel.querySelector('#dz-status');
                    if (el) { el.textContent = m; el.style.color = '#ffb020'; }
                } catch (e) { }
            };
            const arm = (on) => {
                try {
                    const b = panel && panel.querySelector('#dz-go');
                    const i = panel && panel.querySelector('#dz-q');
                    if (b) { b.disabled = !on; b.style.opacity = on ? '' : '0.5'; b.style.cursor = on ? 'pointer' : 'default'; b.textContent = on ? 'Find the mutations' : 'Working…'; }
                    if (i) i.disabled = !on;
                } catch (e) { }
            };
            arm(false);
            // EVERY STEP THE SERVER NARRATES REACHES THE PANEL. Both lookups already report
            // what they are doing -- reading the words, choosing among the phenotypes they
            // matched, finding the genes -- and that was being dropped on the floor, which
            // is why the slowest part of the whole operation was also the quietest.
            const em = new EngineMonitor((m) => { if (m) say('' + m); });
            try {
                say('Reading "' + query + '"…');
                const o = await exec(server + '/py/bio/omim-variants.py', em, query, '' + DZ_MAX_GENES);
                if (!o || o.error) throw new Error((o && o.error) || 'the condition could not be read');
                const J = (x) => { try { return JSON.parse(x || '[]'); } catch (e) { return []; } };
                let genes = J(o.genes), mims = J(o.mims).map((m) => '' + m);
                let disease = ('' + (o.disease || query)).trim() || query;
                let byGeneOnly = false, bySymbol = false;
                if (!genes.length) {
                    // NO INHERITED PHENOTYPE IS NOT THE END OF THE QUESTION.
                    //
                    // ClinVar files variants against OMIM phenotypes, which are inherited
                    // conditions. A somatic tumor -- lung adenocarcinoma, DIPG -- has no
                    // phenotype behind it, so the first route finds nothing and used to stop
                    // there, telling the user their perfectly ordinary question was the wrong
                    // shape. But the genes such a condition is defined by are well known, and
                    // once they are named the rest of the pipeline is unchanged: real
                    // pathogenic ClinVar records, at real coordinates, in those genes.
                    //
                    // Only the GENE NAMES come from the second route. No variant is taken from
                    // it, so nothing recalled is ever drawn -- the marks are still ClinVar's.
                    // A GENE SYMBOL IS NOT A CONDITION, AND IS THE COMMONEST THING TYPED.
                    //
                    // The box invites a gene symbol and then had no route for one: the first
                    // lookup asks which OMIM phenotype the words mean and a gene is not a
                    // phenotype, the second asks which genes a condition is defined by and a
                    // gene is not a condition. Both correctly answered nothing, and the
                    // failure told the user to try the thing they had just tried.
                    //
                    // Asked of the annotation instead it is a one-line question with a fact
                    // for an answer. An EXACT symbol or synonym only: "achondroplasia" must
                    // not be dragged onto some gene whose name happens to contain it, and a
                    // real condition should go on to the route below.
                    if (/^[A-Za-z0-9][A-Za-z0-9._-]{0,24}$/.test(query)) {
                        say('Looking for the gene ' + query.toUpperCase() + '…');
                        try {
                            const gl0 = await exec(server + '/py/bio/gene-locus.py', em, query, (r.species || 'human'), '8');
                            let hits = [];
                            try { hits = JSON.parse((gl0 && gl0.genes) || '[]'); } catch (e2) { hits = []; }
                            const exact = hits.filter((h) => h.matched === 'symbol' || h.matched === 'synonym');
                            if (exact.length) {
                                genes = [('' + exact[0].gene).toUpperCase()];
                                disease = ('' + exact[0].gene).toUpperCase();
                                mims = [];
                                byGeneOnly = true; bySymbol = true;
                            }
                        } catch (e2) { }
                    }
                }
                if (!genes.length) {
                    say('Finding the genes "' + query + '" is defined by…');
                    let g2 = [];
                    try {
                        const o2 = await exec(server + '/py/bio/disease-variants.py', em, query, '24');
                        const raw = (o2 && o2.genes);
                        g2 = Array.isArray(raw) ? raw.slice() : J(raw);
                        if (o2 && o2.disease) disease = ('' + o2.disease).trim() || disease;
                    } catch (e2) { g2 = []; }
                    genes = g2.map((x) => ('' + (x && x.gene ? x.gene : x)).trim().toUpperCase())
                        .filter(Boolean).filter((x, i, a) => a.indexOf(x) === i).slice(0, DZ_MAX_GENES);
                    mims = [];
                    byGeneOnly = genes.length > 0;
                }
                if (!genes.length) {
                    arm(true); dzBusy = false;
                    fail('Nothing could be found for "' + query + '" — neither an inherited condition ClinVar '
                        + 'files variants against, nor a set of genes this is defined by. Try the condition’s '
                        + 'clinical name, or a gene symbol.');
                    return;
                }
                say(disease + ' — ' + genes.length + ' gene' + (genes.length === 1 ? '' : 's')
                    + ': ' + genes.join(', ') + '. Finding where they sit…');
                const gl = await exec(server + '/py/bio/gene-locus.py', em, genes.join(','), (r.species || 'human'), '400');
                let loci = [];
                try { loci = JSON.parse((gl && gl.genes) || '[]'); } catch (e) { loci = []; }
                if (!loci.length) throw new Error('none of these genes could be placed on this genome');
                // The VCF is built rather than the marks placed directly: addVcf is the one
                // road into the chromosomes, and everything that already works -- the sample
                // columns, the significance colouring, the object cap, the per-chromosome
                // sort -- works because every loader goes down it.
                const rows = [];
                const perGene = {};
                const dzBands = [];
                // GENES OVERLAP, AND A RECORD IN THE OVERLAP IS ONE RECORD. Two genes whose
                // spans share bases are read as two windows, and every ClinVar record in the
                // shared part comes back from both. The ingest test only knows what is
                // already drawn, not what this same batch has queued, so the batch dedupes
                // itself here.
                const seenRow = new Set();
                const rowMeta = [];
                let scanned = 0, offMim = 0, dupRows = 0;
                for (let i = 0; i < loci.length; i++) {
                    const g = loci[i];
                    const sym = ('' + (g.query || g.gene || '')).toUpperCase();
                    const ci = chromIndexOf(g.chr);
                    if (ci < 0 || !(+g.start > 0)) continue;
                    say(disease + ' — reading ClinVar for ' + sym + ' (' + (i + 1) + ' of ' + loci.length + ')…');
                    let vs = [];
                    try { vs = await dzFetch(('' + g.chr).replace(/^chr/, ''), Math.round(g.start), Math.round(g.end), 0); }
                    catch (e) { vs = []; }
                    let kept = 0;
                    for (const v of vs) {
                        scanned++;
                        if (!dzIsPathogenic(v)) continue;
                        // THE PHENOTYPE FILTER, when there is one. A gene carries records for
                        // every condition it is implicated in, and loading all of them would
                        // answer a different question than the one asked. Matching on the MIM
                        // ids the lookup resolved is exact where matching on names is guessing
                        // at wording. With no MIMs resolved the gene's pathogenic records are
                        // taken whole, which is the honest fallback and is said so below.
                        if (mims.length) {
                            const vm = (v.mims || []).map((x) => '' + x);
                            if (!vm.length || !vm.some((x) => mims.indexOf(x) >= 0)) { offMim++; continue; }
                        }
                        const ref = ('' + (v.ref || '')).toUpperCase();
                        const alt = ('' + (v.alt || '')).toUpperCase();
                        if (!/^[ACGTN]+$/.test(ref) || !/^[ACGTN]+$/.test(alt)) continue;
                        // THE NAME A MARK WEARS ON THE CHROMOSOME. The ID column of a VCF
                        // becomes the label the genome browser draws beside a variant, and
                        // ClinVar's ID is a variation number -- "925574" says nothing to
                        // anyone reading a chromosome. The label is therefore the DISEASE,
                        // put through the same shortening the loader's selectors use, so the
                        // mark on the bar and the side it belongs to say the same words. The
                        // ClinVar id is not lost: it moves into INFO, where the info panel
                        // and the download still carry it.
                        const clnId = ('' + (v.id || '')).replace(/\s+/g, '');
                        const id = (function () { try { return shortFile(disease) || disease; } catch (e) { return disease; } })()
                            .replace(/[\s\t;,]+/g, '_') || '.';
                        // The record's OWN chromosome, not the gene's. They agree today, but
                        // the gene locus is a separate lookup and a disagreement between them
                        // should place the variant where ClinVar says it is.
                        const chr = ('' + (v.chr || g.chr || ''));
                        const rowKey = chr + ':' + v.start + ':' + ref + ':' + alt;
                        if (seenRow.has(rowKey)) { dupRows++; continue; }
                        seenRow.add(rowKey);
                        rows.push([chr, '' + v.start, id, ref, alt, '.', '.',
                            'CLNSIG=' + dzSig(v).replace(/[;\t ,]+/g, '_')
                            + ';GENEINFO=' + sym
                            + (clnId ? ';CLNVARID=' + clnId : '')].join('\t'));
                        // WHAT THIS ROW CAN BE NARROWED ON, kept beside it. Counting these
                        // afterwards off the VCF text would mean parsing back out what was
                        // just written, and the phenotype names are not in the text at all.
                        rowMeta.push({ gene: sym, sig: dzSig(v) || 'not stated',
                            phen: Array.isArray(v.conditions) ? v.conditions : [] });
                        kept++;
                        if (kept >= DZ_MAX_PER_GENE) break;
                    }
                    if (kept) {
                        perGene[sym] = kept;
                        dzBands.push({ ci: ci, lo: Math.round(+g.start), hi: Math.round(+g.end), gene: sym, n: kept });
                    }
                    await new Promise((res) => setTimeout(res, 0));
                }
                if (!rows.length) {
                    arm(true); dzBusy = false;
                    fail('No pathogenic ClinVar record for ' + disease + ' fell inside '
                        + genes.join(', ') + '. ' + (scanned ? scanned.toLocaleString() + ' records were read.' : ''));
                    return;
                }
                // ABOVE A CERTAIN NUMBER, DRAWING THEM ALL ANSWERS A BROADER QUESTION THAN
                // THE ONE ASKED. A gene or a condition can carry hundreds of pathogenic
                // records covering every phenotype it has ever been implicated in, and a
                // chromosome painted with all of them says less than one painted with the
                // ones that matter. So past DZ_PROMPT the choice goes to the person, with
                // the subsets counted for them so it is a choice they can actually make.
                if (rows.length > DZ_PROMPT) {
                    const pick = await dzChoose(disease, rows, rowMeta, say, arm, panel);
                    if (!pick) { arm(true); dzBusy = false; beatStop(); return; }   // cancelled
                    if (pick.keep) {
                        const kept = [], keptMeta = [];
                        for (let i2 = 0; i2 < rows.length; i2++) {
                            if (!pick.keep(rowMeta[i2])) continue;
                            kept.push(rows[i2]); keptMeta.push(rowMeta[i2]);
                        }
                        if (kept.length) {
                            rows.length = 0; Array.prototype.push.apply(rows, kept);
                            rowMeta.length = 0; Array.prototype.push.apply(rowMeta, keptMeta);
                            // The per-gene counts and the bands follow the narrowing, or the
                            // chromosome would be banded for genes nothing was kept from.
                            for (const kk of Object.keys(perGene)) delete perGene[kk];
                            for (const m2 of rowMeta) perGene[m2.gene] = (perGene[m2.gene] || 0) + 1;
                            for (let bi = dzBands.length - 1; bi >= 0; bi--) {
                                if (!perGene[dzBands[bi].gene]) dzBands.splice(bi, 1);
                                else dzBands[bi].n = perGene[dzBands[bi].gene];
                            }
                        }
                    }
                }
                say('Placing ' + rows.length.toLocaleString() + ' mutation' + (rows.length === 1 ? '' : 's') + '…');
                await new Promise((res) => setTimeout(res, 0));
                await addVcf(rows.join('\n'), disease);
                // THE SAME LABEL A LOADED FILE GETS.
                //
                // ClinVar is a sites-only VCF -- it carries no genotype columns -- so this is
                // exactly the case of loading a sites-only file, and it is named the same way.
                // The side takes the source's name, and every selector built on sideName()
                // then says the disease: the differential picker, the loss-of-heterozygosity
                // picker, and what is loaded. Without it these marks arrived anonymously and
                // read as 'right file' beside whatever else was on the chromosomes.
                //
                // Set only now, for the same reason readAnyFile sets it only on marks landing:
                // naming a side after a source that drew nothing labels a gutter holding
                // somebody else's variants.
                try { sideFile[loadSide] = disease; } catch (e) { }
                // BAND THE GENES THEMSELVES. Marks alone put a few thousand dots inside CFTR
                // and nothing that says CFTR: at whole-genome zoom they are a smudge on 7q,
                // and the per-variant labels do not help either, since names are only kept
                // while the whole genome holds fewer than OBJECT_CAP marks and a loaded VCF
                // spends that budget long before a disease is asked for. A band is the thing
                // that survives both -- drawn at any zoom, named, and clickable -- and it is
                // the same mechanism the loss matrix uses to point at a gene.
                //
                // Only the previous DISEASE bands are cleared, not every banded result: asking
                // for a second disease should not silently throw away a loss matrix.
                try {
                    // SEARCHES ACCUMULATE. Asking about a second condition adds to the
                    // genome, it does not replace what the first one put there: the marks
                    // already behave that way, and the bands that name them have to as well,
                    // or the picture and its labels disagree about what is loaded. Only an
                    // identical band -- same gene, same disease -- is skipped, so asking
                    // twice does not stack two copies of the same label.
                    const already = new Set((regions || []).filter((rg) => rg.dz)
                        .map((rg) => rg.i + ':' + rg.gene + ':' + (rg.disease || '')));
                    for (const b of dzBands.slice(0, LOF_BAND_MAX)) {
                        if (already.has(b.ci + ':' + b.gene + ':' + disease)) continue;
                        regions.push({ i: b.ci, lo: b.lo, hi: b.hi, gene: b.gene, lof: true, dz: true,
                            disease: disease,
                            label: b.gene + ' \u2014 ' + disease + ' \u00b7 ' + b.n.toLocaleString()
                                + ' mutation' + (b.n === 1 ? '' : 's') });
                    }
                    if (graph.wake) graph.wake();
                } catch (e) { step('disease bands failed: ' + e); }
                dzLast = disease;
                beatStop();
                try { if (panel && panel.parentNode) panel.parentNode.removeChild(panel); } catch (e) { }
                const named = Object.keys(perGene).map((k) => k + ' ' + perGene[k]).join(', ');
                graph.setResultMessage(' ' + disease + ' — ' + rows.length.toLocaleString() + ' pathogenic mutation'
                    + (rows.length === 1 ? '' : 's') + ' on ' + Object.keys(perGene).length + ' gene'
                    + (Object.keys(perGene).length === 1 ? '' : 's') + ': ' + named + '.'
                    + (mims.length ? '' : (bySymbol
                        ? ' Read as a gene rather than a condition, so every pathogenic record in it was taken, whatever phenotype it is filed against.'
                        : (byGeneOnly
                            ? ' No inherited phenotype is filed for this, so the genes it is defined by were read instead and every pathogenic record in them was taken.'
                            : ' No phenotype filter was available, so every pathogenic record in these genes was taken.')))
                    + ' ');
                step('disease "' + query + '" -> ' + disease + ': ' + rows.length + ' variants, '
                    + scanned + ' scanned, ' + offMim + ' other phenotypes');
                dzBusy = false;
            } catch (e) {
                beatStop();
                dzBusy = false;
                arm(true);
                fail('That did not work: ' + (e && e.message ? e.message : e));
            }
        };
